"use strict";(globalThis.webpackChunkpaper=globalThis.webpackChunkpaper||[]).push([[989],{6673:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/Grow_Together","metadata":{"permalink":"/paper/books/Grow_Together","source":"@site/books/Grow_Together.md","title":"\ud568\uaed8\uc790\ub77c\uae30","description":"\uc774 \ucc45\uc5d0\uc11c\ub294 \uc77c\ud558\ub294 \ubc29\ubc95\uc758 \ud575\uc2ec\uacfc \ud1b5\ucc30\uc744 \ub2e4\ub8ec\ub2e4. \uac1c\uc778\uc758 \ud798\uc73c\ub85c\ub294 \uadf9\ubcf5\ud560 \uc218 \uc5c6\ub294 \ud55c\uacc4\ub97c \uae68\ub728\ub9ac\ub824\uba74 \ubaa8\ub450\uac00 \uac19\uc774 \ubc1c\uc804\ud574\uc57c \ud55c\ub2e4. \ub098 \uadf8\ub9ac\uace0 \ub354 \ub098\uc544\uac00 \ub0a8\uc744 \ubcc0\ud654\uc2dc\ud0a4\ub294 \uc0b6\uc5d0 \ub300\ud574 \uc598\uae30\ud55c\ub2e4.","date":"2024-12-20T00:00:00.000Z","tags":[],"readingTime":23.59,"hasTruncateMarker":false,"authors":[{"name":"\uae40\ucc3d\uc900","key":null,"page":null}],"frontMatter":{"title":"\ud568\uaed8\uc790\ub77c\uae30","description":"\uc774 \ucc45\uc5d0\uc11c\ub294 \uc77c\ud558\ub294 \ubc29\ubc95\uc758 \ud575\uc2ec\uacfc \ud1b5\ucc30\uc744 \ub2e4\ub8ec\ub2e4. \uac1c\uc778\uc758 \ud798\uc73c\ub85c\ub294 \uadf9\ubcf5\ud560 \uc218 \uc5c6\ub294 \ud55c\uacc4\ub97c \uae68\ub728\ub9ac\ub824\uba74 \ubaa8\ub450\uac00 \uac19\uc774 \ubc1c\uc804\ud574\uc57c \ud55c\ub2e4. \ub098 \uadf8\ub9ac\uace0 \ub354 \ub098\uc544\uac00 \ub0a8\uc744 \ubcc0\ud654\uc2dc\ud0a4\ub294 \uc0b6\uc5d0 \ub300\ud574 \uc598\uae30\ud55c\ub2e4.","image":"https://image.yes24.com/goods/67350256/XL","date":"2024-12-20T00:00:00.000Z","authors":[{"name":"\uae40\ucc3d\uc900"}]},"unlisted":false,"nextItem":{"title":"\ubbf8\uc6c0\ubc1b\uc744 \uc6a9\uae30 2","permalink":"/paper/books/Courage_ToBe_Disliked2"}},"content":"## Chatper 1. \uc790\ub77c\uae30(\ud559\uc2b5)\\n\\n### \ud83d\udc69\ud83c\udffb\u200d\ud83d\udd27 \ud53c\ub4dc\ubc31\uacfc \uad50\uc815\\n- \ud53c\ub4dc\ubc31\uc744 \uc9e7\uc740 \uc8fc\uae30\ub85c \uc5bb\ub294 \uac83, \uadf8\ub9ac\uace0 \uc2e4\uc218\ub97c \uad50\uc815\ud560 \uae30\ud68c\uac00 \uc788\ub294 \uac83\\n- \ub0b4\uac00 \uc798\ud588\ub098 \ubabb \ud588\ub098 \uc54c\uc9c0 \ubabb\ud558\uba74 \ud589\ub3d9\uc744 \uc870\uc815\ud560 \uc218 \uc5c6\ub2e4. \ud559\uc2b5\uc5d0\uc11c\ub294 \ud53c\ub4dc\ubc31\uacfc \uc801\uc808\ud55c \ud53c\ub4dc\ubc31 \uc2dc\uc810\uc774 \uc911\uc694\ud558\ub2e4.\\n\\n### \ud83e\ude9c \ubd80\ud2b8\uc2a4\ud2b8\ub7a9\ud551(bootstrapping)\\n- \ub9e4\uc77c \uc5b4\uc81c\ubcf4\ub2e4 \ub098\uc740 \ub0b4\uac00 \ub418\uae30 \uc704\ud55c \uacfc\uc815\\n- \uc55e\uc5d0\uc11c \ub9cc\ub4e0 \uacb0\uacfc\ubb3c\uc744 \ub098\uc758 \uc77c\ubd80\ub85c \ub9cc\ub4e4\uc5b4, \ub2e4\uc74c \ub2e8\uacc4\uc5d0 \ubcf4\ud0ec\uc774 \ub418\ub3c4\ub85d \ud55c\ub2e4.\\n- 3\uac00\uc9c0 \uc791\uc5c5\\n  - A\uc791\uc5c5 : \uc870\uc9c1\uc774 \ud558\uae30\ub85c \ub418\uc5b4\uc788\ub294 \uc77c\uc744 \ud558\ub294 \uac83 - \uc790\ub3d9\ucc28 \ub9cc\ub4e4\uae30\\n  - B\uc791\uc5c5: A\uc791\uc5c5\uc744 \uac1c\uc120 \ud558\ub294 \uac83 - \uc81c\ud488 \ub9cc\ub4dc\ub294 \uc0ac\uc774\ud074\uc5d0\uc11c \uc2dc\uac04\uacfc \ud488\uc9c8\uc744 \uac1c\uc120, \uc2dc\uc2a4\ud15c \uc124\uacc4\\n  - C\uc791\uc5c5: B\uc791\uc5c5\uc744 \uac1c\uc120\ud558\ub294 \uac83 - \uac1c\uc120 \uc0ac\uc774\ud074 \uc790\uccb4\uc758 \uc2dc\uac04\uacfc \ud488\uc9c8\uc744 \uac1c\uc120\\n- \uc774\uac78 \uc798\ud558\ub824\uba74?\\n  - \uc790\uc2e0\uc774 \uc774\ubbf8 \uac16\uace0 \uc788\ub294 \uac83\ub4e4\uc744 \ud65c\uc6a9\ud558\uae30 - \uc774\ubbf8 \uc2b5\ub4dd\ud55c \uc9c0\uc2dd\uc744 \ucda9\ub3cc\uc2dc\ud0a4\uace0 \uc5f0\uacb0\ud558\ub77c.\\n  - \uc678\ubd80 \uc790\uadf9\uc744 \uc7ac\ube68\ub9ac \uc790\uae30\ud654 \ud558\uae30\\n  - \uc791\uc5c5\uc744 \ub418\ub3cc\uc544\ubcf4\ub294 \ud504\ub85c\uc138\uc2a4 \ub9cc\ub4e4\uae30\\n  - \uc0ac\uc774\ud074 \ud0c0\uc784\uc744 \uc904\uc5ec\uc11c \ud53c\ub4dc\ubc31 \uc790\uc8fc \ubc1b\uae30\\n  - \ud658\uacbd\uc744 \uc810\uc9c4\uc801\uc73c\ub85c \uac1c\uc120\ud558\uae30, \uc644\ubcbd\uc5d0 \uc9d1\ucc29\ud574\uc120 \uc548\ub41c\ub2e4.\\n\\n### \ud83e\udd16 \ud559\uc2b5\ud558\uae30 \ud798\ub4e0 \uc9c1\uc5c5\uc774 \uc0b4\uc544 \ub0a8\ub294\ub2e4.\\n- \uc778\uacf5\uc9c0\ub2a5 \uc2dc\uc2a4\ud15c\uc5d0 \uc720\ub9ac\ud55c \uc870\uac74\\n  - \ubaa9\ud45c\uac00 \ubd84\uba85, \uac1d\uad00\uc801, \uc815\uc801\\n  - \ub9e4 \uc21c\uac04 \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \ud589\ub3d9/\uc120\ud0dc\uc758 \uc885\ub958\uac00 \uc720\ud55c\\n  - \ub9e4 \uc21c\uac04 \uc790\uc2e0\uc758 \ubaa9\ud45c\uc5d0 \uc5bc\ub9c8\ub098 \ub3c4\ub2ec\ud588\ub294\uc9c0 \uce21\uc815 \uac00\ub2a5\\n  - \uc608\uc0c1\uce58 \ubabb\ud55c \uc678\ubd80 \uc694\uc18c\uac00 \uc5c6\ub294 \ud658\uacbd\\n  - \uacfc\uac70\uc758 \uc120\ud0dd\uacfc \uacb0\uacfc\uc5d0 \ub300\ud55c \uad6c\uc870\ud654\ub41c \uae30\ub85d\uc774 \ub9ce\uc74c\\n- \ud559\uc2b5\ud558\uae30 \uc26c\uc6b4 \uc601\uc5ed : \ud53c\ub4dc\ubc31\uc774 \uc8fc\uc5b4\uc9c0\uace0, \uc791\uc5c5\uc774 \ubc18\ubcf5\ub418\uba70, \uac1d\uad00\uc801\uc778 \ubd84\uc11d\uc774 \uac00\ub2a5\\n- \ud559\uc2b5\ud558\uae30 \uc5b4\ub824\uc6b4 \uc601\uc5ed: \ub3c5\ucc3d\uc131, \uc0ac\ud68c\uc801 \ubbfc\uac10\uc131(\ud0c0\uc778\uc758 \ubc18\uc751\uc744 \uc54c\uc544\ucc28\ub9ac\uace0 \uadf8 \uc0ac\ub78c\uc758 \ubc18\uc751\uc744 \uc774\ud574\ud558\uae30), \ud611\uc0c1, \uc124\ub4dd, \ud0c0\uc778\uc744 \ub3d5\uace0 \ub3cc\ubcf4\uae30\\n- \ucef4\ud4e8\ud130\ud654 \ud560 \uc218 \uc788\uc744 \uc218\ub85d (= \ud559\uc2b5\ud558\uae30 \uc26c\uc6b4 \uc601\uc5ed \uc77c\uc218\ub85d) \uc784\uae08\uc774 \ub0ae\uace0 \ub300\uccb4\ub418\uae30 \uc27d\ub2e4.\\n- \ud63c\uc790\uc11c \ub531 \uc815\ud574\uc9c4 \uc77c\ub9cc \ud560 \uc218 \uc788\ub294 \ud658\uacbd\uc774 \ucd95\ubcf5\uc774 \uc544\ub2c8\ub77c \uc800\uc8fc\uac00 \ub420 \uc218 \uc788\ub2e4. \uc554\ubb35\uc9c0\uc640 \uc9c1\uad00\uc744 \ubc30\uc6b0\uace0 \uc218\ub828\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6cc\uc57c \ud55c\ub2e4.\\n\\n### \ud83e\udd7c \ub2ec\uc778\uc774 \ub418\ub824\uba74\\n- \ub3d9\uae30 : \uc2e4\ub825\uc744 \uac1c\uc120\ud558\ub824\ub294 \ub3d9\uae30\\n- \ud53c\ub4dc\ubc31 : \uad6c\uccb4\uc801\uc778 \ud53c\ub4dc\ubc31\uc744 \uc801\uc808\ud55c \uc2dc\uae30\uc5d0\\n\\n### \ud83e\udd7c \uc804\ubb38\uac00\uac00 \ub418\ub824\uba74\\n- \ud0c0\ub2f9\uc131: \uc9c1\uad00\uc774 \uc801\uc6a9\ub418\ub294 \uc601\uc5ed\uc5d0 \uc5b4\ub290\uc815\ub3c4 \uc778\uacfc\uad00\uacc4\uc640 \uaddc\uce59\uc131\uc774 \uc874\uc7ac\\n  - \ud0c0\ub2f9\uc131\uc744 \ub192\uc774\ub824\uba74? \ubcc0\uc218\ub97c \uc81c\ud55c\ud558\uace0 \uc2e4\ud5d8\uc744 \ud558\uba74\uc11c \uaddc\uce59\uc131\uacfc \uc778\uacfc\uad00\uacc4\ub97c \ucc3e\uc73c\ub824\uace0 \ub178\ub825\ud574\uc57c \ud568\\n- \ud53c\ub4dc\ubc31: \uc790\uc2e0\uc774 \ub0b4\ub9b0 \uc9c1\uad00\uc801 \ud310\ub2e8\uc5d0 \ub300\ud574 \ube68\ub9ac \ud53c\ub4dc\ubc31\uc744 \ubc1b\uace0 \uc774\ub97c \ud1b5\ud574 \ud559\uc2b5\ud560 \uae30\ud68c\uac00 \uc8fc\uc5b4\uc9c0\ub294 \ud658\uacbd\\n  - \ud53c\ub4dc\ubc31\uc744 \ub192\uc774\ub824\uba74? \uc9c1\uc811 \ud53c\ub4dc\ubc31\uc744 \uc801\uadf9\uc801\uc73c\ub85c \uad6c\ud574\uc57c \ud568\\n\\n### \ud83c\udfcc\ud83c\udffb\u200d\u2640\ufe0f \uc758\ub3c4\uc801 \uc218\ub828(Deliberate Practice)\\n- \uc758\ub3c4\uc801 \uc218\ub828\uc740 \uc5b4\ub5bb\uac8c \ud574\uc57c\ud558\ub294\uac00? \ud6a8\uacfc\uc801\uc778 \uc758\ub3c4\uc801 \uc218\ub828\uc774 \ub418\uae30 \uc704\ud574\uc11c\ub294?\\n- \uc801\uc808\ud55c \ub09c\uc774\ub3c4\\n  - \uc791\uc5c5\uc758 \ub09c\uc774\ub3c4\uc640 \uc2e4\ub825\uc774 \ube44\ub840\ud560 \ub54c \uac00\uc7a5 \ubab0\uc785\ud560 \uc218 \uc788\ub2e4. \uc801\uc808\ud558\uac8c \ub09c\uc774\ub3c4\uc640 \uc2e4\ub825\uc744 \uc870\uc815\ud574 \ub098\uac00\uc57c \ud55c\ub2e4. \uc774\ub807\uac8c \uac10\uc815 \uc0c1\ud0dc\ub97c \uc0b4\ud53c\uace0 \uc870\uce58\ub97c \ucde8\ud558\ub294 \uc0ac\uc774\ud074\uc744 \uacc4\uc18d \ub3cc\uc544\uc57c \ud55c\ub2e4. \ub09c\uc774\ub3c4\ub97c \uc77c\uc2dc\uc801\uc73c\ub85c \ub09c\ucd94\uc5b4 \ubab0\uc785\uc744 \uacbd\ud5d8\ud55c \ud6c4, \ub09c\uc774\ub3c4\ub97c \ub192\uc774\ub294 \uacbd\uc6b0 \ub354 \uc88b\uc740 \ud559\uc2b5\ud6a8\uacfc\uac00 \uc0dd\uae34\ub2e4. \ub610\ud55c, \uc26c\uc6b4 \uc791\uc5c5\uc744 \uba3c\uc800 \ud558\ub294 \ud3b8\uc774 \uc815\ud655\ub3c4\uac00 \ub192\ub2e4.\\n  - \ud300\uc7a5\ub4e4\uc5d0\uac8c\ub294 \ud300\uc6d0\uc758 \uc0c1\ud0dc\ub97c \ud30c\uc545\ud558\uace0 \uadf8 \ubab0\uc785\uc73c\ub85c \uac00\uac8c \ub3c4\uc640\uc8fc\ub294 \uac83 \uc790\uccb4\uac00 \uace0\ub3c4\uc758 \uc758\ub3c4\uc801 \uc218\ub828\uc774 \ub420 \uc218 \uc788\ub2e4.\\n- \uc778\uc9c0 \ubd80\ud558 \uc774\ub860(cognitive Load Theory)\\n  - \ud559\uc2b5 \uc2dc \ubd88\ud544\uc694\ud558\uac8c \uc778\uc9c0\uc801\uc778 \ubd80\ub2f4\uc744 \uc8fc\uba74 \uc5b4\ub5a4 \uac83\ub3c4 \uc81c\ub300\ub85c \ud559\uc2b5\ud558\uae30 \uc5b4\ub835\ub2e4.\\n\\n### \u23cf\ufe0f \uc804\ubb38\uc131\uc744 \ud6a8\uacfc\uc801\uc73c\ub85c \ubf51\uc544\ub0b4\ub294 \ubc29\ubc95\\n- \uad6c\uccb4\uccb4\uc801\uc778 \uc0ac\uac74\uc5d0 \ub300\ud574 \ub9d0\ud558\ub3c4\ub85d \uc720\ub3c4\ud558\ub294 \uac83\\n- \uc804\ubb38\uac00\ub4e4\uc758 \uc804\ubb38\uc131\uc744 \ubf51\uc544\ub0b4\uace0 \uc801\uc6a9\ud558\ub294 \uac83\uc774 \uc790\uc2e0\uc758 \uc804\ubb38\uc131\uc744 \ube68\ub9ac \ub192\uc774\ub294 \ubc29\ubc95\uc774\ub2e4.\\n- \uc774\ubbf8 \uc798\ud558\ub294 \uc0ac\ub78c\uc744 \uad00\ucc30\ud558\uace0 \uc778\ud130\ubdf0\ud558\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud558\ub294 \uac83\uc774 \ud070 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.\\n\\n### \ud83e\udef3\ud83c\udffb \uc2e4\uc218\ub294 \uc608\ubc29\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uad00\ub9ac\ud558\ub294 \uac83\uc774\ub2e4.\\n- \uc2e4\uc218 \uad00\ub9ac \ubb38\ud654: \uc2e4\uc218\uac00 \ub098\uc05c \uacb0\uacfc\ub97c \ub0b4\uae30 \uc804\uc5d0 \ube68\ub9ac \ud68c\ubcf5\ud558\ub3c4\ub85d \ub3d5\uace0, \uc2e4\uc218\ub97c \uacf5\uac1c\ud558\uace0, \uc2e4\uc218\uc5d0 \ub300\ud574 \uc11c\ub85c \uc774\uc57c\uae30 \ud558\uace0 \ubc30\uc6b8 \uc218 \uc788\ub294 \ubd84\uc704\uae30\\n- \uc2e4\uc218 \ud6c8\ub828: \uc2e4\uc218\ub97c \ucd5c\uc18c\ud654 \ud558\ub294 \uac83\ubcf4\ub2e4 \uc624\ud788\ub824 \uc2e4\uc218\ub97c \uc720\ub3c4\ud558\uace0 \uacbd\ud5d8\ud558\ub294 \uac83\uc744 \uaca9\ub824, \uc2e4\uc218 \uc0ac\ub840\ub97c \ubc30\uc6b0\uace0 \uc5b4\ub5bb\uac8c \ub300\ucc98\ud558\ub294\uac00\ub97c \uac00\ub974\uce58\ub294 \uad50\uc721\uc774 \ub354 \ud6a8\uacfc\uc801\\n- \uc2a4\uc2a4\ub85c\uc5d0\uac8c \uc9c8\ubb38: \uc790\uc2e0\uc758 \uc2e4\uc218 \ubb38\ud654\ub97c \uc608\ubc29\uc5d0\uc11c \uad00\ub9ac\ub85c \uc62e\uaca8\uac00\ub824\uba74 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud560\uae4c?\\n\\n### \ud83e\udd37\ud83c\udffb\u200d\u2640\ufe0f \uc65c \ubc30\uc6cc\ub3c4 \ubabb\ud560 \uae4c?\\n- \uc778\uc9c0\uc801 \uc791\uc5c5 \ubd84\uc11d\\n  - \ub300\ubd80\ubd84\uc758 \ud6c8\ub828\uc740 6\uac1c\uc6d4 \uc815\ub3c4\uac00 \uc9c0\ub098\uba74 \ud6a8\uacfc\uac00 \uac70\uc758 \uc0ac\ub77c\uc9c4\ub2e4. \uc804\ubb38\uac00\ub294 \uc790\uc2e0\uc758 \uc9c0\uc2dd\uc911 70%\ub294 \uac00\ub974\uce58\uc9c0 \uc54a\uace0\uc11c \ub2e4 \uac00\ub974\ucce4\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uc790\uc2e0\uc774 \ud558\ub294 \uc77c\uc774 \ubc18\ubcf5\uc801\uc73c\ub85c \ubab8\uc5d0 \uc775\uace0 \uc790\ub3d9\ud654\ub418\uc5b4\uc11c \uacb0\uad6d \uc554\ubb35\uc801\uc774 \ub418\uc5b4\ubc84\ub9b0\ub2e4. \uc624\ud788\ub824 \uc778\uc2dd\uc774 \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \ubb38\uc81c\ub97c \ud574\uacb0 \ud560 \ub54c \uc5b4\ub5a4 \uacfc\uc815\uc744 \uac70\uce58\ub294\uc9c0 \uc790\uc2e0\uc758 \uba38\ub9bf\uc18d\uc744 \uad00\ucc30\ud558\uace0, \uc9c8\ubb38\uc744 \ub358\uc9c0\uace0, \ubd84\uc11d\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \\n- \uc0ac\ud68c\uc801 \uc790\ubcf8 : \uc2e0\ub8b0, \ub124\ud2b8\uc6cc\ud06c\\n  - \uc5b4\ub5a4 \uae30\uc220\uc801 \uc2e4\ucc9c\ubc95\uc774\ub77c\ub3c4 \uadf8\uac78 \ud604\uc2e4\uc5d0\uc11c \uc801\uc6a9\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc0ac\ud68c\uc801 \uc790\ubcf8\uacfc \uae30\uc220\uc774 \ud544\uc694\ud558\ub2e4. \uc0ac\ud68c\uc801 \uc790\ubcf8\uc740 \uc2e0\ub8b0\ub97c \uc758\ubbf8\ud55c\ub2e4. \uc2e0\ub8b0\uac00 \uae68\uc5b4\uc838 \uc788\ub2e4\uba74 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ud574\ub3c4 \uc545\uc758\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc0ac\ud68c\uc801 \ub124\ud2b8\uc6cc\ud06c \ub610\ud55c \uc790\ubcf8\uc774\ub2e4. \ub6f0\uc5b4\ub09c \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uac1c\ubc1c\uc790\uc77c \uc218\ub85d \ud0c0\uc778\uacfc \uc778\ud130\ub809\uc158\uc5d0 \ub354 \ub9ce\uc740 \uc2dc\uac04\uc744  \uc4f4\ub2e4.\\n- \uc0ac\ud68c\uc801 \uae30\uc220 : \ub3c4\uc6c0 \ubc1b\uae30, \ud53c\ub4dc\ubc31 \uc8fc\uace0\ubc1b\uae30, \uc601\ud5a5\ub825 \ubbf8\uce58\uae30, \uac00\ub974\uce58\uace0 \ubc30\uc6b0\uae30, \uc704\uc784\ud558\uae30 \ub4f1\\n- \uc0ac\ud68c\uc801 \uae30\uc220\uc740 \uc5b4\ub5bb\uac8c \ud6c8\ub828\ud560\uae4c?\\n  - \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uacfc\uc758 \uc778\ud130\ub809\uc158\uc744 \uc2e0\uacbd\uc4f0\uc790. \uae30\ub85d\ud558\uace0, \ubcf5\uae30\ud558\uace0, \ub2e4\ub974\uac8c \uc778\ud130\ub799\uc158\ud55c\ub2e4\uace0 \ud558\uba74 \uc5b4\ub5bb\uac8c \ud588\uc73c\uba74 \uc88b\uc558\uc744\uae4c\ub97c \uc0dd\uac01\ud574 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \ud6c8\ub828\uc774 \ub41c\ub2e4.\\n\\n## Chatper 2. \ud568\uaed8(\ud611\ub825)\\n\\n### \ud83d\udcd1 \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uad00\ub9ac\uc790\uc758 \uac1c\uc120 \uc6b0\uc120 \uc21c\uc704\\n- \uad00\ub9ac \u2192 \uc2dc\uc2a4\ud15c \u2192 \uc0ac\ub78c \u2192 \ub3c4\uad6c\\n- \uac00\uc7a5 \ub9cc\ub9cc\ud558\uace0 \uc26c\uc6b4 (\uc790\uc2e0\uc73c\ub85c\ubd80\ud130 \uac00\uc7a5 \uba3c \uac83) \'\ub3c4\uad6c\'\uc5d0 \uc2e0\uacbd \uc4f0\ub294 \uac83 \ubcf4\ub2e4, \uc790\uc2e0\uc744 \ub3cc\uc544\ubcf4\uace0 \uad00\ub9ac \ubc29\uc2dd \uc790\uccb4\ub97c \uc0b4\ud3b4\ubcf4\uace0 \uac1c\uc120\ud558\ub294 \uac83\uc774 \ucd9c\ubc1c\uc774 \ub41c\ub2e4.\\n\\n### \ud83d\udce6 \ucd94\uc0c1\ud654\\n\ub6f0\uc5b4\ub09c \ud504\ub85c\uadf8\ub798\uba38\ub294 \ubcf4\ud1b5 \uc2e4\ub825\uc744 \uac00\uc9c4 \ud504\ub85c\uadf8\ub798\uba38\uc5d0 \ube44\ud574 \ucee4\ubba4\ub2c8\ucf00\uc774\uc158, \ud611\ub825 \ub2a5\ub825\uc774 \ub6f0\uc5b4\ub09c\ub2e4. \uac8c\ub2e4\uac00 \uc774\uc5d0 \uc624\ub79c \uc2dc\uac04\uc744 \ub4e4\uc774\uae30 \uae4c\uc9c0 \ud55c\ub2e4. \\n\uc5ec\ub7ec\uba85\uc5d0\uc11c \uc791\uc5c5\ud558\uba74 \uc11c\ub85c \uc2dc\uac01\uc774 \ub2e4\ub974\uae30 \ub584\ubb38\uc5d0 \ub2e4\ub978 \uc2dc\uac01\uc744 \uc5f0\uacb0\ud574 \uc904 \ub2e4\ub9ac\uac00 \ud544\uc694\ud558\uace0, \uadf8 \ub2e4\ub9ac\uc5d0\ub294 \ud544\uc5f0\uc801\uc73c\ub85c \ucd94\uc0c1\ud654\uc758 \uc694\uc18c\uac00 \uc788\uac8c \ub41c\ub2e4. \\n\ucd94\uc0c1\ud654\ub97c \ub192\uc77c \uc218 \uc788\ub294 \ubc29\ubc95\uc740 \'\ub2e4\ub978 \uc2dc\uac01\uc744 \uac00\uc9c4 \ub450 \uc0ac\ub78c\uc774 \ud611\ub825\ud558\uae30\'\uc774\ub2e4.\\n\\n### \ud83d\udd17 \uacf5\uc720\\n\uc2e0\ub8b0 \uc790\uc0b0\uc774 \ub192\uc740 \uc870\uc9c1\uc740 \ucee4\ubba4\ub2c8\ucf00\uc774\uc158 \ud6a8\uc728\uc774\ub098 \uc0dd\uc0b0\uc131\uc774 \ub192\ub2e4. \uadf8\ub807\ub2e4\uba74 \uc5b4\ub5bb\uac8c \uc2e0\ub8b0\ub97c \uc313\uc744 \uc218 \uc788\uc744\uae4c?\\n\uc2e0\ub8b0\ub97c \uc313\ub294 \ub370 \uc0ac\uc6a9\ub418\ub294 \ubc29\ubc95\uc740 \ud22c\uba85\uc131\uacfc \uacf5\uc720, \uc778\ud130\ub809\uc158\uc774\ub2e4. \ud22c\uba85\ud558\uac8c \uc11c\ub85c \uacf5\uc720\ud558\uace0 \uadf8\uc5d0 \ub300\ud574 \ud53c\ub4dc\ubc31\uc744 \uc8fc\uace0 \ubc1b\uc73c\uba70 \uc778\ud130\ub809\uc158\uc744 \ud558\ub294 \uac83\uc774\ub2e4. (=\uc18c\ud1b5\uc2e0\ub8b0)\\n\uadf8\ub7f0\ub370 \uc774\ub7f0 \uacf5\uc720\uac00 \uc2e0\ub8b0\ub97c \ub5a8\uc5b4\ub728\ub9ac\uae30\ub3c4 \ud55c\ub2e4. \\n\\n- \ubcf5\uc218\uacf5\uc720(share multiple)\\n- \ucd5c\uace0 \uacf5\uc720(share best)\\n- \ud558\ub098\uacf5\uc720(share one)\\n\\n\ud558\ub098\ub9cc \uacf5\uc720\ud558\ub294 \uacbd\uc6b0 \'\uc791\uc5c5\ubb3c = \ub098\' \uac00 \ub418\uc5b4 \ubc29\uc5b4\uc801\uc73c\ub85c \ub300\uc751\ud558\uba70, \uc0c1\ub300\ub3c4 \uc194\uc9c1\ud55c \ud53c\ub4dc\ubc31\uc744 \uc8fc\uae30 \uc5b4\ub824\uc6cc\uc11c \uc2e0\ub8b0\ub3c4\uac00 \ub5a8\uc5b4\uc9c4\ub2e4. \ubc18\uba74, \ubcf5\uc218 \uacf5\uc720\ub294 \uadf8\ub7f0 \ubd88\uc548\uac10\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc801\uace0, \uc2e0\ub8b0\ub3c4\uac00 \ub192\uc544\uc9c4\ub2e4.\\n\uadf8\ub0e5 \uacf5\uc720\ub9cc \ud55c\ub2e4\uace0 \uc2e0\ub8b0\uac00 \uc800\uc808\ub85c \uc313\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \uc774\ud574\ud558\uace0, \uc5b4\ub5bb\uac8c \uacf5\uc720\ud560 \uac83\uc778\uc9c0 \uace0\ubbfc\ud574\ubcf4\uc790.\\n\\n### \ud83d\udc71\ud83c\udffb\u200d\u2640\ufe0f \uac1d\uad00\uc131\uc758 \uc8fc\uad00\uc131\\n\uc758\uc0ac\uacb0\uc815\uc744 \ud558\ub294 \uacfc\uc815\uc5d0 \uac10\uc815\uc801\uc774\uace0 \uc9c1\uad00\uc801\uc778 \ubd80\ubd84\uc774 \ud070 \uc5ed\ud560\uc744 \ud558\uace0 \uc788\uc73c\uba70, \uadf8\ub7f0 \uac10\uc815\uc801\uc778 \ubd80\ubd84\uc774 \ubc30\uc81c\ub41c\ub2e4\uba74 \uc758\uc0ac\uacb0\uc815\uc744 \uc81c\ub300\ub85c \ud560 \uc218 \uc5c6\ub2e4.\\n\uc124\ub4dd\uc744 \uc704\ud574 \uac1d\uad00\uc131\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uac1d\uad00\uc131\uc774\ub77c\uace0 \ud558\ub294 \uac83\uc740 \uc0c1\ub300\uc801\uc774\ub2e4. \ub0b4\uac00 \uc0dd\uac01\ud558\ub294 \uac1d\uad00\uc774 \uc0c1\ub300\uc758 \uac1d\uad00\uc774 \uc544\ub2d0 \uc218 \uc788\uace0, \uadf8\ub807\uae30 \ub54c\ubb38\uc5d0 \uc124\ub4dd\uc5d0 \uc131\uacf5\ud558\ub824\uba74 \uc6b0\uc120 \uadf8 \uc0ac\ub78c\uc744 \uc774\ud574\ud558\ub294 \uac83\uc5d0\uc11c \ucd9c\ubc1c\ud574\uc57c \ud55c\ub2e4.\\n\\n### \ud83d\udc68\ud83c\udffb\u200d\ud83c\udfeb \ucf54\uce6d\\n\uc6a9\uae30\ub97c \ub0b4\uc5b4 \uc9c8\ubb38\ud55c \ub3d9\ub8cc\uc5d0\uac8c \'\uc774\uac83\ub3c4 \ubaa8\ub974\uc138\uc694?\' \ub77c\uace0 \ub9d0\ud558\uba74 \uc5b4\ub5a4 \uc0c1\ud669\uc774 \ubc8c\uc5b4\uc9c8\uae4c? \ub300\ubd80\ubd84\uc758 \uacbd\uc6b0 \ub2e4\uc2dc \uc9c8\ubb38\uc744 \ud558\uc9c0 \uc54a\ub294\ub2e4.\\n\ub300\ud654\ub97c \ud1b5\ud574 \uc0c1\ub300\uac00 \uc5b4\ub5a4 \uc2dd\uc73c\ub85c \uc774\ud574\ud558\uace0 \uc788\ub294\uc9c0, \ubaa8\ub974\ub294 \ubb38\uc81c\ub97c \ub9cc\ub0ac\uc744 \ub54c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud558\ub824\uace0 \uc2dc\ub3c4\ud558\ub294\uc9c0, \uc790\uc2e0\uc758 \ub2f5\uc774 \ub9de\ub294\uc9c0\ub97c \uc5b4\ub5bb\uac8c \ud655\uc778\ud558\ub294\uc9c0 \ub4f1\uc744 \uc54c \uc218 \uc788\ub2e4. \uadf8 \uc0ac\ub78c\uc758 \uc0ac\uace0 \uacfc\uc815\uacfc \uc804\ub7b5\uc744 \uc774\ud574\ud568\uc73c\ub85c\uc368 \ub354 \uc815\ud655\ud558\uace0 \ud6a8\uacfc\uc801\uc778 \uc81c\uc548\uc744 \ud560 \uc218 \uc788\uac8c \ub41c\ub2e4.\\n\uaf2d \uc804\ubb38\uc9c0\uc2dd\uc774 \uc5c6\uc774\ub3c4 \ucf54\uce6d\uc744 \ud560 \uc218 \uc788\ub2e4. \ud589\ub3d9\uc744 \uc720\ub3c4\ud558\ub294 \ub300\ud654 \ub9cc\uc73c\ub85c \ucf54\uce6d\uc740 \ucda9\ubd84\ud558\ub2e4.\\n\\n### \ud83d\udd1d \ud0d1\ub2e4\uc6b4(top-down) \ubc29\uc2dd\uacfc \ubc14\ud140\uc5c5(bottom-up)\ubc29\uc2dd\\n\uc138\uc0c1\uc758 \ubb38\uc81c\ub294 \ub450\uc885\ub958\ub85c \ub098\ub258\uc5b4\uc9c4\ub2e4. \uc798 \uc815\uc758\ub41c \ubb38\uc81c(well-defined)\uc640 \uc798 \uc815\uc758\ub418\uc9c0 \uc54a\uc740(ill-defined)\ubb38\uc81c.\\n\uc798 \uc815\uc758\ub418\uc9c0 \uc54a\uc740 \ubb38\uc81c\ub294 \ud0d1\ub2e4\uc6b4\uacfc \ubc14\ud140\uc5c5\uc744 \uc11e\uc5b4\uc11c \uc811\uadfc\ud55c\ub2e4. \ud604\uc7ac \ubb38\uc81c\uac00 \uc5bc\ub9c8\ub098 \uc5b4\ub824\uc6b4\uac00\ub97c \uc778\uc2dd\ud558\uace0 \ubb38\uc81c \ud480\uc774 \uc804\ub7b5\uc744 \uc0c1\ud669\uc5d0 \ub9de\uac8c \ub2a5\ub3d9\uc801\uc73c\ub85c \uc120\ud0dd\ud558\uac70\ub098 \ubcc0\uacbd\ud574\uc57c \ud55c\ub2e4. \ud0d1\ub2e4\uc6b4 \ubc29\uc2dd\uc740 \uc911\uac04 \uc911\uac04\uc758 \ubc14\ud1b5\ud130\uce58\uc5d0 \ub9ce\uc740 \uc624\ubc84\ud5e4\ub4dc\uac00 \ubc1c\uc0dd\ud55c\ub2e4. \uc624\ubc84\ud5e4\ub4dc\ub97c \ub0ae\ucd94\ub824\uba74 \ud611\ub825 \ubaa8\ub378\uc774 \ubc14\ud1b5 \ud130\uce58 \ubaa8\ud615\uc5d0 \uae30\ubc18\ud558\uc9c0 \uc54a\uace0 \uc0bc\ud22c\uc555 \ubaa8\ud615\uc73c\ub85c \uac00\uac8c\ub41c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uae54\ub054\ud558\uace0 \uccb4\uacc4\uc801\uc73c\ub85c \uc9c4\ud589\ud558\uae30\ub97c \uace0\ubbfc\ud558\uae30 \ubcf4\ub2e4, \uc5b4\ub5bb\uac8c \ud558\uba74 \ucc98\uc74c\ubd80\ud130 \uac01 \ub2e8\uacc4(ex. \ubd84\uc11d, \uc124\uacc4, \uad6c\ud604, \ud14c\uc2a4\ud2b8)\ub97c \ubaa8\ub450 \uc654\ub2e4\uac14\ub2e4\ud560 \uc218 \uc788\uc744 \uae4c\ub97c \uace0\ubbfc\ud574\uc57c \ud55c\ub2e4.\\n\\n* \uc0bc\ud22c\uc555\uc801 \uc758\uc0ac\uc18c\ud1b5: \'\ubc30\uc5b4\ub4dc\ub294\' \uc18c\ud1b5\ubc29\uc2dd\\n\\n### \ud83d\ude8c \uc804\ubb38\uac00 \ud300\uc758 \uc2e4\ud328\\n\'\ubc84\uc2a4\uc5d0 \uc0ac\ub78c\ud0dc\uc6b0\uae30\'\ub77c\ub294 \uba54\ud0c0\ud3ec\uac00 \uc788\ub2e4. \ubc84\uc2a4\uc5d0 \uc801\uc808\ud55c \uc0ac\ub78c\uc744 \ud0dc\uc6b0\ub294 \uac83\uc774 \uc6b0\uc120\uc774\uace0, \uc5b4\ub514\ub85c \uac08\uc9c0 \uc815\ud558\ub294 \uac74 \uadf8 \ub2e4\uc74c\uc774\ub77c\ub294 \ub9d0\uc774\ub2e4.\\n\uacfc\uc5f0 \uc804\ubb38\uac00\ub4e4\uc744 \ubaa8\uc544 \ub454\ub2e4\uba74 \ub354 \uc798 \ud560 \uc218 \uc788\uc744\uae4c? \uc911\uac04\uc5d0 \ud611\ub825\uc744 \uac1c\uc785\ud558\ub294 \uc0ac\ub78c\uc774 \uc5c6\ub2e4\uba74 \uc804\ubb38\uac00\ub4e4\ub85c \uad6c\uc131\ub41c \ud300\uc740 \uc815\ubcf4 \uacf5\uc720\uac00 \uc548 \ub418\uc5b4\uc11c \uc624\ud788\ub824 \uc131\uacfc\uac00 \ub5a8\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc815\ubcf4\ub97c \uacf5\uc720\ud558\uace0 \ud611\ub825\uc744 \uc798\ud558\uae30 \uc704\ud55c \uba85\uc2dc\uc801\uc778 \ub3c4\uc6c0\uc774 \ud544\uc694\ud558\ub2e4.\\n\\n### \ud83d\udd11 \uad6c\uae00\uc774 \ubc1d\ud78c \ud0c1\uc6d4\ud55c \ud300\uc758 \ube44\ubc00\\n- \ub6f0\uc5b4\ub09c \uad00\ub9ac\uc790\uc758 \ud2b9\uc9d5\uc744 \ucc3e\ub294 \uc625\uc2dc\uc804 \ud504\ub85c\uc81d\ud2b8(Oxygen Project)\uc758 \uacb0\uacfc\\n  - \ud300\uc5d0 \ub204\uac00 \uc788\ub294\uc9c0(\uc804\ubb38\uac00, \ub0b4\ud5a5/\uc678\ud5a5, \uc9c0\ub2a5 \ub4f1)\ubcf4\ub2e4 \ud300\uc6d0\ub4e4\uc774 \uc11c\ub85c \uc5b4\ub5bb\uac8c \uc0c1\ud638\uc791\uc6a9\ud558\uace0 \uc790\uc2e0\uc758 \uc77c\uc744 \uc5b4\ub5bb\uac8c \ubc14\ub77c\ubcf4\ub294\uc9c0\uac00 \ud6e8\uc52c \uc911\uc694\ud588\ub2e4.\\n  - 5\uac00\uc9c0 \uc131\uacf5\uc801 \ud300\uc758 \ud2b9\uc9d5\uc744 \ucc3e\uc558\uc740\ub370, \uadf8\uc911 \uc555\ub3c4\uc801\uc73c\ub85c \ub192\uc740 \uc608\uce21\ub825\uc744 \ubcf4\uc778 \ubcc0\uc218\ub294 \ud300\uc758 \uc2ec\ub9ac\uc801 \uc548\uc804\uac10(Psychological Safety)\uc774\uc5c8\ub2e4.\\n    - \uc2ec\ub9ac\uc801 \uc548\uc804\uac10\uc774\ub780? \ub0b4 \uc0dd\uac01\uc774\ub098 \uc758\uacac, \uc9c8\ubb38, \uac71\uc815, \ud639\uc740 \uc2e4\uc218\uac00 \ub4dc\ub7ec\ub0ac\uc744 \ub54c \ucc98\ubc8c\ubc1b\uac70\ub098 \ub180\ub9bc\ubc1b\uc9c0 \uc54a\uc744 \uac70\ub77c\ub294 \ubbff\uc74c\uc744 \ub9d0\ud55c\ub2e4.\\n  - \ud300 \ud1a0\ub860 \ub4f1 \ud2b9\ubcc4\ud788 \uace0\uc548\ub41c \ud65c\ub3d9\uc744 \ud1b5\ud574 \uc2ec\ub9ac\uc801 \uc548\uc804\uac10\uc744 \uac1c\uc120\ud560 \uc218 \uc788\uc5c8\ub2e4.\\n\\n\uadf8\ub807\ub2e4\uba74 \uc2ec\ub9ac\uc801 \uc548\uc804\uac10\uc744 \ub192\uc774\ub824\uba74 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud560\uae4c?\\n- \ud1a0\ub860 \uc8fc\uc81c\ub97c \uc548\uc804\ud55c \ud658\uacbd\uc5d0\uc11c \uc774\uc57c\uae30\ud558\uac8c \ud574\uc8fc\ub294 \uac83\\n- \uc5f4\ub9b0 \ub300\ud654\ub97c \uc2dc\uc791\ud558\ub294 \uac83\\n\\n### \ud83d\udcc8 \ud559\uc2b5 \uc18d\ub3c4\\n- \ud559\uc2b5 \uc18d\ub3c4\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc694\uc18c\\n  - \ud559\uc2b5 \ud658\uacbd: \ud559\uc2b5\uc5d0 \ub300\ud55c \ud0dc\ub3c4, \uc2ec\ub9ac\uc801 \ubcf4\ud638 \\n  - \ub9ac\ub354: \ud559\uc2b5 \ud658\uacbd\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294 \ub9ac\ub354\uac00 \ud544\uc694\ud558\ub2e4.\\n- \ud559\uc2b5 \uc18d\ub3c4\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\uc740 \uc694\uc18c\\n  - \uad50\uc721 \ubc30\uacbd, \uacbd\ud5d8, \uacbd\ub825 \uc5f0\ucc28\\n- \ud604\uc2e4\uc5d0\uc11c \ud559\uc2b5 \uc18d\ub3c4\ub97c \uac1c\uc120\ud558\ub824\uba74?\\n  - \ud559\uc2b5 \ud658\uacbd \ub9cc\ub4e4\uae30\\n  - \ud559\uc2b5 \uacf5\ub3d9\uccb4 \uad6c\ucd95\ud558\uae30\\n\\n### \ud83c\udd9a \uc778\uc9c0\uc801 \ud3b8\ud5a5\\n- \ud1b5\uc0c1 \uc2dc\uac04\uc744 \ucd94\uc815\ud560 \ub54c \uc6b0\ub9ac\ub294 \ub300\ud46f\uac12\uc73c\ub85c \ucd5c\ube48\uac12\uc744 \uc120\ud0dd\ud558\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.\\n- \uc77c\uc758 \uc18c\uc694 \uc2dc\uac04\uc744 \ucd94\uc815\ud560 \ub54c \uc0ac\ub78c\ub4e4\uc774 \ub099\uacfc\uc801\uc73c\ub85c \ucd94\uc815\ud558\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.\\n- \uadf8\ub7f4\uc2f8\ud55c \ucd94\uc815\uce58(best guess)\uc640 \uc790\uc2e0\uc774 \uae30\ub300\ud558\ub294 \ucd5c\uc120\uc758 \uc0c1\ud669(best case scenario)\ub97c \ucd94\uc815\uce58\ub294 \ud070 \ucc28\uc774\uac00 \uc5c6\ub2e4.\\n- \uc9c1\uad00\uc758 \ud5c8\uc810\\n  - \'\uadf8\ub9ac\uace0(AND)\' \uc870\uac74\uc758 \uc0ac\uac74\uc740 \ud655\ub960\uc744 \uacfc\ub300\ud3c9\uac00\ud558\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.\\n  - \'\ub610\ub294(OR)\' \uc870\uac74\uc758 \uc0ac\uac74\uc740 \ud655\ub960\uc744 \uacfc\uc18c\ud3c9\uac00\ud558\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.\\n\\n12\uba85\uc758 \uc0ac\ub78c\uacfc 12\uac00\uc9c0\uc758 \uc77c\uc774 \uc788\ub2e4\uace0 \uac00\uc815\ud574 \ubcf4\uc790. \uace0\uc804\uc801\uc778 \ubc29\uc2dd\uc5d0\uc11c\ub294 12\uba85\uc774 \uac01\uc790 \ud55c \uac00\uc9c0 \uc77c\uc744 \ub9e1\uc544 \uc9c4\ud589\ud558\uc9c0\ub9cc, \uc560\uc790\uc77c \ubc29\uc2dd\uc5d0\uc11c\ub294 \uc77c\uc744 \uacf5\uc720\ud558\uace0 \ud611\ub825\ud55c\ub2e4. \uc560\uc790\uc77c\uc5d0\uc11c\ub294 \uc77c\uc744 \uba3c\uc800 \ub05d\ub0b8 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ub3c4\uc640\uc8fc\ubbc0\ub85c, \uc804\uccb4 \uc791\uc5c5\uc774 \uc81c\ub54c \uc644\ub8cc\ub420 \ud655\ub960\uc774 \ub192\uc544\uc9c4\ub2e4. \ub610\ud55c, \uc560\uc790\uc77c\uc740 \uc9c0\uc2dd\uc744 \uacf5\uc720\ud558\uc5ec \ud504\ub85c\uc81d\ud2b8 \uc18d\ub3c4\ub97c \ub192\uc774\ub294\ub370, \uc774\ub294 \ubaa8\ub450\uac00 \ud568\uaed8 \uc774\ub4dd\uc744 \ubcf4\ub294 \'\ub610\ub294\' \ud655\ub960\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc560\uc790\uc77c\uc740 \uae0d\uc815\uc801\uc778 \uacb0\uacfc\uc5d0 \ub300\ud574 \'\uadf8\ub9ac\uace0\' \ud655\ub960\uc744 \'\ub610\ub294\' \ud655\ub960\ub85c \ubc14\uafb8\uace0, \ubd80\uc815\uc801\uc778 \uc0c1\ud669\uc5d0\uc11c\ub294 \uadf8 \ubc18\ub300\ub85c \uc801\uc6a9\ud558\ub294 \ud2b9\uc9d5\uc774 \uc788\ub2e4.\\n\\n## Chatper 3. \uc560\uc790\uc77c\\n\\n### \ud83c\udfaf \uc560\uc790\uc77c \uc774\ub780?\\n- \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uac1c\ubc1c \ubc29\ubc95\ub860\\n- \'\uae30\ubbfc\ud55c\' \ud639\uc740 \'\ubbfc\ucca9\ud55c\' \ub73b\uc73c\ub85c \ubc88\uc5ed\ud55c\ub2e4. \uc608\uc0c1\ud558\uc9c0 \ubabb\ud588\ub358 \uc0c1\ud669\uc774 \uc0dd\uacbc\uc744 \ub54c \ub300\uc751\uc744 \uc798 \ud560 \uc218 \uc788\ub2e4\ub294 \ub73b\uc774\ubbc0\ub85c \uc77c\ubc18\uc801\uc778 \'\ube60\ub978\'\uacfc\ub294 \ucc28\ubcc4\uc131\uc774 \uc788\ub2e4.\\n\\n\uc560\uc790\uc77c\uc740 \ubd88\ud655\uc2e4\uc131\uc774 \ud074 \ub54c \uc6b0\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uc9c0\ub97c \uace0\ubbfc\ud55c \uacb0\uacfc\ubb3c\uc774\ub2e4. \uc880 \ub354 \uc9e7\uc740 \uc8fc\uae30\ub85c \ub354 \ub2e4\uc591\ud55c \uc0ac\ub78c\ub4e4\ub85c \ubd80\ud130 \ub354 \uc790\uc8fc \uadf8\ub9ac\uace0 \ub354 \uc77c\ucc0d \ud53c\ub4dc\ubc31\uc744 \ubc1b\ub294 \uac83\uc73c\ub85c \uc815\ub9ac\ud560 \uc218 \uc788\ub2e4.\\n\\n### \ud83c\udfc1 \uc560\uc790\uc77c\uc744 \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud560 \uc218 \uc788\uc744 \uae4c?\\n\\n\uc560\uc790\uc77c\uc774 \ubd88\ud655\uc2e4\uc131\uc744 \ub2e4\ub8e8\ub294 \ud575\uc2ec \uad6c\ub3d9 \uc6d0\ub9ac\ub294 **\ud559\uc2b5**\uacfc **\ud611\ub825** \uc989, \ud568\uaed8(\ud611\ub825) \uc790\ub77c\uae30 \uc774\ub2e4. \ubd88\ud655\uc2e4\uc131\uc774 \ub192\uc744 \uc218\ub85d \ubaa9\ud45c\uc810\uc5d0 \ub3c4\ub2ec\ud558\uae30\uae4c\uc9c0 \ub098\uc758 \uc704\uce58\ub97c \uacc4\uc18d \ud655\uc778\ud558\uba70 \uc774\ub3d9\ud558\uba74\uc11c \ubc30\uc6cc \ub098\uac00\uc57c \ud55c\ub2e4. \ub610\ud55c, \uc11c\ub85c\uc758 \uc5c5\ubb34\ub97c \uacf5\uc720\ud558\uace0 \uc0c1\ud638\uac80\ud1a0\ud558\ub294 \ud611\ub825\uc744 \ud1b5\ud574 \ubb38\uc81c\uac00 \uc0dd\uae38 \ud655\ub960\uc744 \'\uadf8\ub9ac\uace0\' \uc870\uac74\uc73c\ub85c \ubc14\uafbc\ub2e4.\\n\\n### \ud83d\udc8c \uc560\uc790\uc77c\uc758 \ud575\uc2ec \uc6d0\ub9ac - \uace0\uac1d\uc5d0\uac8c \ub9e4\uc77c \uac00\uce58\ub97c \uc804\ud558\ub77c.\\n1. **\ud559\uc2b5 \uce21\uba74**: \'\ub9e4\uc77c\' \uac00\uce58\ub97c \uc804\ud558\ub294 \uac83\uc740 \ud559\uc2b5 \ube48\ub3c4\ub97c \ub192\uc774\ub294 \uac83\uc744 \uc758\ubbf8\ud558\uba70, \ubd88\ud655\uc2e4\uc131\uc774 \ud074\uc218\ub85d \uc790\uc8fc \ud53c\ub4dc\ubc31\uc744 \ubc1b\uc544\uc57c \ud55c\ub2e4. \uc9c4\uc815\ud55c \uac00\uce58\ub97c \uc804\ub2ec\ud574\uc57c \uc815\ud655\ud55c \ud53c\ub4dc\ubc31\uc744 \ubc1b\uace0, \uc774\ub294 \ube60\ub978 \ud559\uc2b5\uacfc \uc131\uc7a5\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4. \uc2dc\uc791\ubd80\ud130 \ube48\ubc88\ud55c \ud53c\ub4dc\ubc31\uc744 \ubc1b\uc73c\uba74 \ud559\uc2b5\uc758 \ubcf5\ub9ac \ud6a8\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\ub2e4,\\n2. **\ud611\ub825 \uce21\uba74**: \'\uace0\uac1d\'\uc740 \ub113\uac8c \ud574\uc11d\ub418\uc5b4 \uc774\ud574\uad00\uacc4\uc790\ub97c \ud3ec\ud568\ud558\uba70, \ud611\ub825\uc744 \ud1b5\ud574 \uac00\uce58\ub97c \uc804\ub2ec\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uac00\uce58\ub97c \uc804\ub2ec\ud558\uba74 \uc2e0\ub8b0\uac00 \uc313\uc774\uace0 \ud611\ub825\uc774 \uc6d0\ud65c\ud574\uc9c0\uba70, \uc758\uc0ac\uc18c\ud1b5\ub3c4 \uba85\ud655\ud574\uc9c4\ub2e4.\\n\\n\uacb0\uad6d, \uc560\uc790\uc77c\uc758 \ud575\uc2ec\uc740 \ud568\uaed8 \uc790\ub77c\uba70 \uc131\uc7a5\ud558\ub294 \uacfc\uc815\uc774\uba70, \uc774\ub97c \ud1b5\ud574 \ub354 \ub098\uc740 \ud611\ub825\uacfc \uc131\uacfc\ub97c \uc774\ub8f0 \uc218 \uc788\ub2e4.\\n\\n### \ud83d\udc6f \uc560\uc790\uc77c \ub3c4\uc785 \uc131\uacf5 \uc694\uc778\\n- \uace0\uac1d \ucc38\uc5ec\\n  - \ud504\ub85c\uc81d\ud2b8\uc758 \uc131\ud328\ub97c \uc88c\uc6b0\ud558\ub294 \uc0ac\ub78c\uacfc \ucd5c\ub300\ud55c \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc744 \ucc38\uc5ec \uc2dc\ucf1c\uc57c \ud55c\ub2e4.\\n- \uc9e7\uc740 \uac1c\ubc1c \uc8fc\uae30\\n- \uc560\uc790\uc77c \ucf54\uce58 - \ud568\uaed8 \uc790\ub77c\uae30\ub97c \uc798\ud558\ub294 \uc0ac\ub78c\\n  - \uc2e0\ucc9c\ubc95\uc744 \ub354 \uc798 \ub3c4\uc785\ud560 \uc218 \uc788\uac8c \ub3c4\uc640\uc900\ub2e4. \uc560\uc790\uc77c \ucf54\uce58\ub294 \ub204\uad6c\ub098 \ub420 \uc218 \uc788\ub2e4. \uc624\ub85c\uc9c0 \uc790\uc2e0\uc758 \uc120\ud0dd\uc774\ub2e4. \uc774 \uc0ac\ub78c\uc774 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud558\uace0 \uc758\uc0ac\uc18c\ud1b5 \ud558\ub290\ub0d0\uc5d0 \ub530\ub77c \ud300\uc758 \ud589\ub3d9\uacfc \uc758\uc0ac\uc18c\ud1b5\uc774 \ubc14\ub014 \uc218 \uc788\ub2e4. \\n  - \ud0c1\uc6d4\ud55c \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uc5d4\uc9c0\ub2c8\uc5b4\uc758 \uc608\ub97c \ub4e4\uc5b4\ubcf4\uc790. \uc8fc\uc5b4\uc9c4 \uc5c5\ubb34\uc678\uc5d0\ub3c4 \uad00\uc2ec\uc744 \uac00\uc9c0\uba70, \ud504\ub85c\uc81d\ud2b8 \uc804\ubc18\uc5d0 \ub300\ud55c \ud070 \uadf8\ub9bc\uc744 \uac00\uc9c0\ub824\uace0 \ud558\uace0, \uacbd\uc601\uc9c4\uc5d0\uac8c \uc801\uadf9\uc801\uc778 \ud0dc\ub3c4\ub85c \ub2e4\uac00\uac00\uace0, \ub2e4\ub978 \uc5d4\uc9c0\ub2c8\uc5b4\ub4e4\uc744 \ub3c4\uc640\uc900\ub2e4.\\n\\n### \ud83d\udc64 \uc65c \ub0b4 \uc870\uc9c1\uc5d0\ub294 \uc0c8 \ubc29\ubc95\ub860\uc774 \uba39\ud788\uc9c0 \uc54a\uc744\uae4c?\\n\\n\'\uce58\ub8cc\uc790 \ud6a8\uacfc\' \ub77c\ub294 \uac83\uc740 \uce58\ub8cc\uc790\uac00 \ub204\uad6c\ub0d0\uc5d0 \ub530\ub77c \uc0c1\ub2f4 \ud6a8\uacfc\uac00 \uc88c\uc6b0\ub418\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4. \uc5b4\ub5a4 \ubc29\ubc95\ub860\uc744 \uc0ac\uc6a9\ud558\ub358 \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \ub204\uac00 \ucc38\uc5ec\ud558\ub294 \uac00\uac00 \uc555\ub3c4\uc801\uc73c\ub85c \uc911\uc694\ud55c \ubb38\uc81c\uac00 \ub41c\ub2e4. \ubcc4 \ubcfc \uc77c \uc5c6\uc5b4 \ubcf4\uc774\ub294 \ubc29\ubc95\ub860\uc77c\uc9c0\ub77c\ub3c4 \uadf8\uac78 \ucc98\ubc29\ud558\ub294 \ud300\uc7a5\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \ud6a8\uacfc\uac00 \uc788\ub2e4.\\n\\n### \ud83e\udec2 \uc560\uc790\uc77c\uc758 \uc131\uacf5\ub960\uc740 \ub192\uc9c0 \uc54a\ub2e4.\\n\\n\uc65c \uadf8\ub7f4\uae4c? \uc560\uc790\uc77c \ubc18\uc560\uc790\uc77c\uc801\uc73c\ub85c \uc801\uc6a9\ud558\uace0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ubaa8\ub4e0 \uc885\ub958\uc758 \ubc29\ubc95\ub860\uc740 \ud0dc\uc0dd\uc801\uc73c\ub85c \ubd88\ud655\uc2e4\uc131\uc774 \ub192\ub2e4. \uadf8\ub7f4 \ub54c \ud604\uba85\ud55c \uc804\ub7b5\uc740 \uc815\ud574\uc9c4 \uc218\uc21c\uc744 \ub530\ub974\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacc1\uc5d0 \uc788\ub294 \uc0ac\ub78c\ub4e4\uacfc \ud568\uaed8 \uc8fc\ubcc0\uc744 \ud0d0\uc0c9\ud558\uace0 \uc870\uae08 \ub098\uc544\uac00\uace0 \ud655\uc778\ud558\uace0\ub97c \ubc18\ubcf5\ud558\uba74\uc11c \uc6b0\ub9ac\uc758 \ud604 \ub9e5\ub77d\uc5d0 \ub9de\ub294 \uc88b\uc740 \uc804\ub7b5\ub4e4\uc744 \uc2a4\uc2a4\ub85c \ub9cc\ub4e4\uc5b4 \ub098\uac00\ub294 \uac83\uc774\ub2e4."},{"id":"/Courage_ToBe_Disliked2","metadata":{"permalink":"/paper/books/Courage_ToBe_Disliked2","source":"@site/books/Courage_ToBe_Disliked2.md","title":"\ubbf8\uc6c0\ubc1b\uc744 \uc6a9\uae30 2","description":"\uc0ac\ub791\uacfc \uc9c4\uc815\ud55c \uc790\ub9bd\uc5d0 \ub300\ud55c \uc544\ub4e4\ub7ec\uc758 \uac00\ub974\uce68","date":"2024-10-10T00:00:00.000Z","tags":[],"readingTime":10.03,"hasTruncateMarker":false,"authors":[{"name":"\uae30\uc2dc\ubbf8 \uc774\uce58\ub85c, \uace0\uac00 \ud6c4\ubbf8\ud0c0\ucf00 \uc800/\uc804\uacbd\uc544 \uc5ed","key":null,"page":null}],"frontMatter":{"title":"\ubbf8\uc6c0\ubc1b\uc744 \uc6a9\uae30 2","description":"\uc0ac\ub791\uacfc \uc9c4\uc815\ud55c \uc790\ub9bd\uc5d0 \ub300\ud55c \uc544\ub4e4\ub7ec\uc758 \uac00\ub974\uce68","image":"https://image.yes24.com/goods/25654204/XL","date":"2024-10-10T00:00:00.000Z","authors":[{"name":"\uae30\uc2dc\ubbf8 \uc774\uce58\ub85c, \uace0\uac00 \ud6c4\ubbf8\ud0c0\ucf00 \uc800/\uc804\uacbd\uc544 \uc5ed"}]},"unlisted":false,"prevItem":{"title":"\ud568\uaed8\uc790\ub77c\uae30","permalink":"/paper/books/Grow_Together"},"nextItem":{"title":"\ub9d0\uc13c\uc2a4","permalink":"/paper/books/We_Need_to_Talk"}},"content":"## \ud83e\uddd0 \uccab \ubc88\uc7ac \uc774\uc57c\uae30 - \ub098\uc05c \uadf8 \uc0ac\ub78c, \ubd88\uc30d\ud55c \ub098\ub77c\ub294 \ud551\uacc4\\n\\n- \uc778\uc0dd\uc744 \uc0ac\ub294 \ud0dc\ub3c4, \uc790\uc2e0\uc758 \ubb34\uc9c0\ub97c \uc544\ub294 \uac83.\\n- \uad50\uc721\uc758 \uad81\uae0d\uc801\uc778 \ubaa9\ud45c\ub294 \uc790\ub9bd\uc774\ub2e4. \uc778\uac04\uc740 \ubaa8\ub450 \uc790\uc720\ub97c \ucd94\uad6c\ud558\uace0, \ubb34\uae30\ub825\ud558\uace0 \ubd80\uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc0c1\ud0dc\uc5d0\uc11c \'\uc790\ub9bd\'\ud558\uae30\ub97c \uc6d0\ud55c\ub2e4. \uadf8 \uc790\ub9bd\uc744 \ucd09\uc9c4\ud558\ub294 \uac83\uc774 \uad50\uc721\uc774\ub2e4.\\n- \'\uc790\ub9bd\'\uc744 \uc9c0\uc6d0\ud558\ub294 \uccab \ub2e8\uacc4\ub294 \'\uc874\uacbd\'\uc774\ub2e4. \uc874\uacbd\uc774\ub780 \uc778\uac04\uc758 \ubaa8\uc2b5\uc744 \uc788\ub294 \uadf8\ub300\ub85c \ubcf4\uace0, \uadf8 \uc0ac\ub78c\uc774 \uc720\uc77c\ubb34\uc774\ud55c \uc874\uc7ac\uc784\uc744 \uc544\ub294 \ub2a5\ub825\uc774\ub2e4. \ub610\ud55c, \uc874\uacbd\uc774\ub780 \uadf8 \uc0ac\ub78c\uc774 \uadf8 \uc0ac\ub78c\ub2f5\uac8c \uc131\uc7a5\ud558\uace0 \ubc1c\uc804 \ud560 \uc218 \uc788\uac8c \ubc30\ub824\ud558\ub294 \uac83\uc774\ub2e4. \uc790\uc2e0\uc758 \uac00\uce58\uad00\uc744 \ubc00\uc5b4\ubd99\uc774\uc9c0 \uc54a\uace0 \uadf8 \uc0ac\ub78c\uc774 \'\uadf8\uc0ac\ub78c \uc778 \uac83\'\uc5d0 \uac00\uce58\ub97c \ub450\ub294 \uac83. \ub098\uc544\uac00\uc11c\ub294 \uadf8 \uc131\uc7a5\uacfc \ubc1c\uc804\uc744 \uc9c0\uc6d0\ud558\ub294 \uac83. \uadf8\uac83\uc774 \ubc14\ub85c \uc874\uacbd\uc774\ub2e4. \uba3c\uc800 \uc874\uacbd\ud558\ub294 \ud0dc\ub3c4\ub97c \ubcf4\uc778\ub2e4\uba74 \ud0c0\uc778\uc774 \uc790\ub9bd\ud560 \uc6a9\uae30\ub97c \uc8fc\ub294 \ud589\ub3d9\uc774\uace0, \uc790\ub9bd\ud560 \uc6a9\uae30\ub97c \ub0b4\ub290\ub0d0 \ub9c8\ub290\ub0d0\ub294 \uc0c1\ub300\uc758 \uacfc\uc81c\uc774\ub2e4.\\n- \'\uc874\uacbd\'\uc744 \uc704\ud55c \uccab \uac78\uc74c\uc740 \'\ud0c0\uc778\uc758 \uad00\uc2ec\uc0ac\'\uc5d0 \uad00\uc2ec\uc744 \uae30\uc6b8\uc774\ub294 \uac83\uc774\ub2e4. \ud0c0\uc778\uc758 \ub208\uc73c\ub85c \ubcf4\uace0, \ud0c0\uc778\uc758 \uadc0\ub85c \ub4e3\uace0, \ud0c0\uc778\uc758 \ub9c8\uc74c\uc73c\ub85c \ub290\ub07c\ub294 \uac83.\\n- \uc6b0\ub9ac\ub294 \uacfc\uac70\uc758 \uc0ac\uac74\uc5d0 \uc758\ud574 \uacb0\uc815\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8 \uc0ac\uac74\uc5d0 \'\uc5b4\ub5a4 \uc758\ubbf8\ub97c \ubd80\uc5ec\ud558\ub294\uac00\'\uc5d0 \ub530\ub77c \uc790\uc2e0\uc758 \uc0b6\uc744 \uacb0\uc815\ud55c\ub2e4.(\ubaa9\uc801\ub860) \uc790\uc2e0\uc758 \uc778\uc0dd\uc744 \uacb0\uc815\ud558\ub294 \uac83\uc740 \'\uc9c0\uae08, \uc5ec\uae30\'\ub97c \uc0ac\ub294 \ub098 \uc774\ub2e4. \uc778\uac04\uc740 \uc5b8\uc81c\ub098 \uc790\uc544\ub97c \uacb0\uc815\ud560 \uc218 \uc788\ub294 \uc874\uc7ac\uc774\ub2e4.\\n- \ub098\uc758 \'\uc9c0\uae08\'\uc774 \uacfc\uac70\ub97c \uacb0\uc815\ud55c\ub2e4. \\n- \uc0bc\uac01\uc8fc, \ud55c\ucabd\uc5d0\ub294 \'\ub098\uc05c \uadf8 \uc0ac\ub78c\', \ub2e4\ub978 \ud55c \ucabd\uc5d0\ub294 \'\ubd88\uc30d\ud55c \ub098\', \ub098\uba38\uc9c0 \ud55c \ucabd\uc5d0\ub294 \'\uc55e\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud560 \uac83\uc778\uac00\'\ub77c\uace0 \uc801\ud600\uc788\ub2e4. \ub098\ub294 \uc138\ubc88 \uc9f8 \uba74\uc5d0 \uc9d1\uc911 \ud574\uc57c\ud55c\ub2e4.\\n\\n## \u2049\ufe0f \ub450 \ubc88\uc9f8 \uc774\uc57c\uae30 - \uc65c \uc0c1\uacfc \ubc8c\uc744 \ubd80\uc815\ud558\ub294 \uac00\\n\\n- \uad50\uc2e4\uc740 \uc791\uc740 \ubbfc\uc8fc\uc8fc\uc758 \uad6d\uac00\ub2e4. \uad50\uc2e4\uc758 \uc8fc\uad8c\uc790\ub294 \ud559\uc0dd\ub4e4\uc774\ub2e4. \uc544\uc774\ub4e4\uc774 \ubab0\ub77c\uc11c \ubb38\uc81c\ud589\ub3d9\uc744 \ud558\uae30\ub3c4 \ud558\uc9c0\ub9cc, \uc54c\uba74\uc11c\ub3c4 \ubb38\uc81c\ud589\ub3d9\uc744 \ud558\uae30\ub3c4 \ud55c\ub2e4. \uba3c\uc800 \ubb38\uc81c\ud589\ub3d9\uc758 \ubaa9\uc801\uc744 \ud30c\uc545\ud558\ub77c.\\n- \ubb38\uc81c\ud589\ub3d9\uc758 5\ub2e8\uacc4 : \ubaa8\ub450 \'\ub098\ub97c \ub354 \uc874\uc911\ud574 \ub2ec\ub77c\'\uace0 \uc0ac\ub791\uc744 \uac08\uad6c\ud558\ub294 \ub9c8\uc74c\uc758 \ud45c\ud604\\n    - 1\ub2e8\uacc4 - \uce6d\ucc2c\uc694\uad6c / \ucc29\ud55c \ud589\ub3d9\uc744 \ud588\uc744 \ub54c\uc5d0\ub9cc \uc8fc\ubaa9\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud3c9\uc18c \'\uad00\uc2ec\uc0ac\'\uc5d0 \uc8fc\ubaa9\ud558\uace0 \uacf5\uac10\ud558\uae30\\n    - 2\ub2e8\uacc4 - \uc8fc\ubaa9 \ub04c\uae30(\uce6d\ucc2c \ubc1b\uc9c0 \uc54a\uc544\ub3c4 \ub418\ub2c8\uae4c \uc5b4\uca0c\ub72c \uc8fc\ubaa9\uc744 \ub04c\uc790) / \uc9c0\uae08\uc774\ub300\ub85c\ub3c4 \ucda9\ubd84\ud788 \uac00\uce58\uac00 \uc788\ub2e4\uace0 \uc874\uacbd\uc744 \ud45c\ud604\ud558\uae30\\n    - 3\ub2e8\uacc4 - \uad8c\ub825\ud22c\uc7c1(\ubd88\ubcf5\uc885\uc744 \ud1b5\ud574 \uc790\uc2e0\uc758 \ud798\uc744 \uc99d\uba85\ud558\ub824\uace0 \ud55c\ub2e4) / \ubb3c\ub7ec\ub098\uae30\\n    - 4\ub2e8\uacc4 - \ubcf5\uc218(\uc774\ub807\uac8c \ub41c \uac83\uc740 \ub2f9\uc2e0 \ud0d3\uc774\ub2e4)\\n    - 5\ub2e8\uacc4 - \ubb34\ub2a5\uc758 \uc99d\uba85(\ub354 \uc774\uc0c1 \ub098\uc5d0\uac8c \uae30\ub300\ud558\uc9c0\ub9c8, \uba38\uc9c0\uc54a\uc544 \'\ubaa8\uc790\ub780 \ub098\'\uac00 \uc9c4\uc815\ud55c \ub098\ub77c\uace0 \ubbff\uac8c \ub41c\ub2e4)\\n- \ubaa8\ub4e0 \ud589\uc704\ub294 \'\uc18c\uc18d\uac10\', \uc989 \'\uacf5\ub3d9\uccb4 \uc548\uc5d0\uc11c \ud2b9\ubcc4\ud55c \uc704\uce58\ub97c \ud655\ubcf4\ud558\ub294 \uac83\'\uc774\ub77c\ub294 \ubaa9\uc801\uc5d0\uc11c \ube44\ub86f\ub41c\ub2e4. \ub2e4\ud230 \uc544\uc774\ub4e4\uc758 \'\ubaa9\uc801\'\uc5d0 \uc8fc\ubaa9\ud558\uace0, \uc544\uc774\ub4e4\uacfc \ud568\uaed8 \'\uc55e\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud560 \uac83\uc778\uac00\'\ub97c \uc0dd\uac01\ud558\ub294 \uac83\uc774 \uad50\uc721\uc790\uc758 \uc5ed\ud560\uc774\ub2e4.\\n- \ud654\ub0b4\ub294 \uac83\uacfc \uc57c\ub2e8 \uce58\ub294 \uac83\uc740 \uac19\ub2e4. \uc57c\ub2e8\uce58\ub294 \uac83\uc740 \uc11c\ub85c\uc758 \'\uc874\uacbd\'\uc744 \ud6fc\uc190\ud558\ub294 \ud589\uc704\uc774\ub2e4.\\n- \ud3ed\ub825\uc740 \uac12 \uc2fc \ucee4\ubba4\ub2c8\ucf00\uc774\uc158\uc774\ub2e4. \ud3ed\ub825\uc5d0 \uc758\uc874\ud558\uba74 \uc2dc\uac04\uacfc \ub178\ub825\uc5c6\uc774\ub3c4 \uc790\uc2e0\uc758 \uc694\uad6c\ub97c \ubc00\uc5b4\ubd99\uc77c \uc218 \uc788\ub2e4. \ub354 \uc9c1\uc811\uc801\uc778 \ud45c\ud604\uc73c\ub85c\ub294 \uc0c1\ud0dc\ub97c \uad74\ubcf5 \uc2dc\ud0ac \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098, \uc0dd\uac01\ud574\uc57c\ud560 \uac83\uc740 \'\uc55e\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud560 \uac83\uc778\uac00\'\uc774\ub2e4.\\n- \'\ubc14\uafc0 \uc218 \uc5c6\ub294 \uac83\'\uc5d0 \uc9d1\ucc29\ud558\uc9c0 \ub9d0\uace0, \ub208 \uc55e\uc5d0 \uc788\ub294 \'\ubc14\uafc0 \uc218 \uc788\ub294 \uac83\'\uc744 \uc9c1\uc2dc\ud558\ub77c.\\n- \uadf8\ub7ec\ub098 \uc5b4\ub978\ub4e4\uc740 \uc544\uc774\ub4e4\uc744 \'\ubbf8\uc131\ub144 \uc0c1\ud0dc\'\uc5d0 \uc7a1\uc544\ub450\ub824\uace0 \ud55c\ub2e4. \ub9cc\uc57d \ud559\uc0dd\uc774 \uc790\ub9bd\ud574\uc11c \uad50\uc721\uc790\uc640 \ub300\ub4f1\ud55c \uc785\uc7a5\uc774 \ub41c\ub2e4\uba74 \uad50\uc721\uc790\uc758 \uad8c\uc704\ub294 \ubb34\ub108\uc9c4\ub2e4. \uc989, \uc218\uc9c1\uad00\uacc4\uac00 \ubb34\ub108\uc9c0\ub294 \uac83\uc744 \ub450\ub824\uc6cc \ud55c\ub2e4. \\n- \uad50\uc721\uc790 \ub354 \ub098\uc544\uac00 \uc870\uc9c1\uc758 \uc6b4\uc601\uc744 \ub9e1\uace0 \uc788\ub294 \ub9ac\ub354\ub294 \ub298 \'\uc790\ub9bd\'\uc744 \ubaa9\ud45c\ub85c \ub0b4\uc138\uc6cc\uc57c \ud55c\ub2e4. \uad50\uc721\uc790\ub294 \uc544\uc774\ub4e4\uc758 \'\uc790\ub9bd\'\uc774\ub77c\ub294 \ubaa9\ud45c\uc5d0 \uacf5\ud5cc\ud588\ub2e4\ub294 \uacf5\ud5cc\uac10\uc744 \uac16\ub294\ub2e4. \uadf8 \uacf5\ud5cc\uac10\uc5d0\uc11c \ud589\ubcf5\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4.\\n- \ubc14\ub78c\uc9c1\ud55c \uad50\uc721\uc790\uc758 \uc790\uc138 - \ubcf8\uc778\uc758 \uc778\uc0dd\uc740, \ub9e4\uc77c\uc758 \ud589\ub3d9\uc740 \uc804\ubd80 \uc2a4\uc2a4\ub85c \uacb0\uc815\ud558\ub294 \uac83\uc774\ub77c\uace0 \uac00\ub974\uccd0\uc904 \uac83. \uadf8\ub9ac\uace0 \uacb0\uc815\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc790\ub8cc(\uc608\ub97c \ub4e4\uba74 \uc9c0\uc2dd\uacfc \uacbd\ud5d8)\uac00 \uc788\uc73c\uba74 \uc81c\uacf5\ud574 \uc904 \uac83. \uc544\uc774\ub4e4\uc758 \uacb0\uc815\uc744 \uc874\uc911\ud558\uace0, \uadf8 \uacb0\uc815\uc744 \uc9c0\uc9c0\ud574\uc8fc\uace0 \ub3c4\uc640\uc8fc\ub77c. \uadf8\ub9ac\uace0 \uc5b8\uc81c\ub4e0 \ub3c4\uc640\uc904 \uc900\ube44\uac00 \ub418\uc5b4 \uc788\ub2e4\uace0 \uc54c\ub824\uc8fc\ub418, \ub108\ubb34 \uac00\uae5d\uc9c0 \uc54a\uc740, \ub3c4\uc6c0\uc744 \uc904 \uc218 \uc788\ub294 \uac70\ub9ac\uc5d0\uc11c \uc9c0\ucf1c\ubcf4\uba74 \ub418\ub294 \uac83.\\n\\n## \ud83e\udd1d\ud83c\udffb \uc138 \ubc88\uc9f8 \uc774\uc57c\uae30 - \uacbd\uc7c1\uc6d0\ub9ac\uac00 \uc544\ub2cc \ud611\ub825\uc6d0\ub9ac\uc5d0 \uae30\ucd08\ud558\ub77c\\n\\n- \uce6d\ucc2c\ud558\ub294 \ud589\uc704\ub294 \uacf5\ub3d9\uccb4 \uc548\uc5d0\uc11c \uacbd\uc7c1\uc6d0\ub9ac\ub97c \ub0b3\uace0, \uc544\uc774\ub4e4\uc5d0\uac8c \'\ud0c0\uc778\uc740 \uc801\uc774\ub2e4\'\ub77c\ub294 \uc0dd\ud65c\uc591\uc2dd\uc744 \uc2ec\uc5b4\uc8fc\uac8c \ub41c\ub2e4.\\n- \ubaa8\ub4e0 \uc778\uac04\uc740 \'\ubd88\uc644\uc804\ud55c \uc874\uc7ac\'\ub85c \uc2dc\uc791\ud574\uc11c \ub204\uad6c\ub098 \uc5f4\ub4f1\uac10\uc744 \uacbd\ud5d8\ud55c\ub2e4. \uc778\uac04\uc740 \uc57d\ud558\uae30 \ub584\ubb38\uc5d0 \uacf5\ub3d9\uccb4\ub97c \ub9cc\ub4e4\uace0 \ud611\ub825\uad00\uacc4\ub97c \ub9fa\uc73c\uba70 \uc0b4\uc544\uac04\ub2e4.\\n- \uc778\uac04\uc774 \uac00\uc9c4 \uac00\uc7a5 \uae30\ubcf8\uc801 \uc695\uad6c\ub294 \'\uc18c\uc18d\uac10\'\uc774\ub2e4(\uc544\ub4e4\ub7ec). \uadf8\ub807\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ud574\uc57c \uc18c\uc18d\uac10\uc744 \uac00\uc9c8 \uc218 \uc788\uc744\uae4c? \ud0c0\uc778\uc73c\ub85c\ubd80\ud130 \uc778\uc815\ubc1b\uae30\ub97c \uc6d0\ud558\uc9c0 \ub9c8\uace0, \uc790\uc2e0\uc758 \uc758\uc0ac\ub85c \uc2a4\uc2a4\ub85c\ub97c \uc778\uc815\ud574\uc57c \ud55c\ub2e4. \'\uc790\ub9bd\'\uc774\ub780 \uc2a4\uc2a4\ub85c \uc790\uc2e0\uc758 \uac00\uce58\ub97c \uacb0\uc815\ud558\ub294 \uac83\uc774\ub2e4.\\n- \ud3c9\ubc94\ud574\uc9c8 \uc6a9\uae30\uac00 \ud544\uc694\ud558\ub2e4. \ud2b9\ubcc4\ud55c \uc874\uc7ac\uac00 \uc544\ub2c8\uc5b4\ub3c4, \ud2b9\ubcc4\ud788 \ub6f0\uc5b4\ub098\uc9c0 \uc54a\uc544\ub3c4 \ub0b4\uac00 \uc788\uc744 \uacf3\uc740 \uac70\uae30\uc5d0 \uc788\ub2e4.\\n- \uccad\ub144\uc740 \ud0c0\uc778\uc744 \uad6c\ud568\uc73c\ub85c\uc368 \uc790\uc2e0\uc744 \uad6c\ud558\ub824\uace0 \ud55c\ub2e4. \uc2a4\uc2a4\ub85c\ub97c \uc77c\uc885\uc758 \uad6c\uc6d0\uc790\ub85c \ud3ec\uc7a5\ud574\uc11c \uc790\uc2e0\uc758 \uac00\uce58\ub97c \uc2e4\uac10\ud558\ub824 \ud55c\ub2e4. \\n- \ud559\uc0dd\ub4e4\uc744 \'\uc77c\'\ub85c\uc11c \ub300\ud558\uc9c0 \ub9d0\uace0 \'\uad50\uc6b0\'\ub85c\uc11c \uad00\uacc4\ub97c \ub9fa\uc5b4\ub77c.\\n\\n## \ud83c\udf81 \ub124 \ubc88\uc9f8 \uc774\uc57c\uae30 - \uc8fc\ub77c, \uadf8\ub7ec\uba74 \uc5bb\uc744 \uac83\uc774\ub2e4\\n\\n- \ubaa8\ub4e0 \uace0\ubbfc\uc740 \uc778\uac04\uad00\uacc4\uc5d0\uc11c \ube44\ub86f\ub41c\ub2e4. \ub9c8\ucc2c\uac00\uc9c0\ub85c \'\ubaa8\ub4e0 \uae30\uc068\ub3c4 \uc778\uad00\uad00\uacc4\uc5d0\uc11c \ube44\ub86f\ub41c\ub2e4\'\\n- \uc2e0\uc6a9\uacfc \uc2e0\ub8b0\uc758 \ucc28\uc774\\n    - \'\uc2e0\uc6a9\'\uc774\ub780 \uc0c1\ub300\uac00 \uac00\uc9c4 \uc870\uac74\uc744 \ubbff\ub294 \uac83\\n    - \'\uc2e0\ub8b0\'\ub780 \uc544\ubb34\ub7f0 \uc870\uac74 \uc5c6\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ubbff\ub294 \uac83\\n- \uc77c\uc758 \uad00\uacc4\ub294 \'\uc2e0\uc6a9\'\uc758 \uad00\uacc4\uc774\uace0, \uad50\uc6b0\uc758 \uad00\uacc4\ub294 \'\uc2e0\ub8b0\'\uc758 \uad00\uacc4\uc774\ub2e4.\\n- \uc0b4\uae30 \uc704\ud574\uc11c\ub294 \ubd84\uc5c5\uc774 \ud544\uc694\ud558\uace0, \ubd84\uc5c5\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc0c1\ud638 \'\uc2e0\uc6a9\'\uc774 \ud544\uc694\ud558\ub2e4. \uac70\uae30\uc5d0 \uc120\ud0dd\uc758 \uc5ec\uc9c0\ub294 \uc5c6\ub2e4. \uc6b0\ub9ac\ub294 \ud63c\uc790\uc11c\ub294 \uc0b4 \uc218 \uc5c6\uace0, \uadf8\ub807\uae30 \ub54c\ubb38\uc5d0 \uc2e0\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc120\ud0dd\uc9c0\ub294 \uc788\uc744 \uc218 \uc5c6\ub2e4. \uad00\uacc4\ub97c \ub9fa\uc5b4\uc57c\ub9cc \ud55c\ub2e4.\\n- \uc778\uac04\uc758 \uac00\uce58\ub294 \'\uc5b4\ub5a4 \uc77c\uc5d0 \uc885\uc0ac\ud558\ub290\ub0d0\'\ub85c \uc815\ud574\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8 \uc77c\uc5d0 \'\uc5b4\ub5a4 \ud0dc\ub3c4\ub85c \uc784\ud558\ub290\ub0d0\'\ub85c \uc815\ud574\uc9c4\ub2e4. \ub9cc\uc57d \uc5b4\ub5a4 \uc77c\uc774 \uac00\uce58\uac00 \uc5c6\ub2e4\uace0 \ud55c\ub2e4\uba74 \uacb0\uad6d \ub3c4\ud0dc\ub41c\ub2e4. \ub3c4\ud0dc\ub418\uc9c0 \uc54a\uace0 \uc0b4\uc544\ub0a8\uc558\ub2e4\uba74 \uadf8 \uc77c\uc5d0\ub294 \uac00\uce58\uac00 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4.\\n- \ud0c0\uc778\uc744 \'\uc2e0\ub8b0\' \ud560 \uc218 \uc788\ub290\ub0d0 \uc5c6\ub290\ub0d0\ub294, \ud0c0\uc778\uc744 \uc874\uacbd\ud560 \uc218 \uc788\ub290\ub0d0 \uc5c6\ub290\ub0d0\uc640 \uc0c1\uad00\uc788\ub2e4.\\n- \uad50\uc721\uc758 \uc785\uad6c\ub294 \uc874\uacbd\uc774\uace0 -> \uc874\uacbd\uc774\ub780 \uc2e0\ub8b0\ub2e4 -> \ub098\uc544\uac00 \uc2e0\ub8b0\ub97c \ubc14\ud0d5\uc73c\ub85c \ud55c \uad00\uacc4\ub294 \uad50\uc6b0\uad00\uacc4\uc774\ub2e4.\\n\\n## \u2764\ufe0f \ub2e4\uc12f \ubc88\uc9f8 \uc774\uc57c\uae30 - \uc0ac\ub791\ud558\ub294 \uc778\uc0dd\uc744 \uc120\ud0dd\ud558\ub77c"},{"id":"/We_Need_to_Talk","metadata":{"permalink":"/paper/books/We_Need_to_Talk","source":"@site/books/We_Need_to_Talk.md","title":"\ub9d0\uc13c\uc2a4","description":"\uc0c1\ub300\uac00 \ub204\uad6c\uc774\ub4e0, \uc5b4\ub5a4 \ub300\ud654 \uc0c1\ud669\uc774\ub4e0 \ubc18\ub4dc\uc2dc \uc9c0\ucf1c\uc57c \ud560 \ub300\ud654\uc758 \uc6d0\uce59\ub4e4\uc744 \uc81c\uc2dc\ud55c\ub2e4.","date":"2024-01-10T00:00:00.000Z","tags":[],"readingTime":12.155,"hasTruncateMarker":false,"authors":[{"name":"\uc140\ub808\uc2a4\ud2b8 \ud5e4\ub4e4\ub9ac","key":null,"page":null}],"frontMatter":{"title":"\ub9d0\uc13c\uc2a4","description":"\uc0c1\ub300\uac00 \ub204\uad6c\uc774\ub4e0, \uc5b4\ub5a4 \ub300\ud654 \uc0c1\ud669\uc774\ub4e0 \ubc18\ub4dc\uc2dc \uc9c0\ucf1c\uc57c \ud560 \ub300\ud654\uc758 \uc6d0\uce59\ub4e4\uc744 \uc81c\uc2dc\ud55c\ub2e4.","image":"https://image.yes24.com/goods/68798451/XL","date":"2024-01-10T00:00:00.000Z","authors":[{"name":"\uc140\ub808\uc2a4\ud2b8 \ud5e4\ub4e4\ub9ac"}]},"unlisted":false,"prevItem":{"title":"\ubbf8\uc6c0\ubc1b\uc744 \uc6a9\uae30 2","permalink":"/paper/books/Courage_ToBe_Disliked2"}},"content":"## \ud83d\udc42\ud83c\udffb 1. \uc8fc\uc778\uacf5\uc774 \ub418\uace0 \uc2f6\uc740 \uc695\uad6c\ub97c \ucc38\uc544\ub0b8\ub2e4.\\n\\n\uc6b0\ub9ac\ub294 \ub300\ud654 \uc911 \ub098\uc758 \uacbd\ud5d8\uc744 \ub098\ub204\uba70 \uacf5\uac10\ud558\ub824 \ud558\uc9c0\ub9cc, \uc624\ud788\ub824 \uc0c1\ub300\ub97c \uc81c\ub300\ub85c \uc774\ud574\ud558\uc9c0 \ubabb\ud558\uac8c \ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \ub1cc\ub294 \ube44\uc2b7\ud55c \uacbd\ud5d8\uc744 \ub5a0\uc62c\ub824 \uacf5\uac10\uc744 \uc720\ub3c4\ud558\uc9c0\ub9cc, \uacb0\uad6d \uc790\uae30 \uc911\uc2ec\uc801\uc778 \uc0ac\uace0\ub85c \uc774\ub8e8\uc5b4\uc9c0\uae30 \uc27d\ub2e4. \ub300\ud654\ub780 \uaf2d \ub9d0\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc73c\uba70, \ub208\ube5b, \ud45c\uc815, \ubab8\uc9d3, \uc2ec\uc9c0\uc5b4 \uce68\ubb35 \uc18d\uc5d0\uc11c\ub3c4 \uacf5\uac10\uc744 \uc804\ub2ec\ud560 \uc218 \uc788\ub2e4.\\n\\n\ud83d\udc69\ud83c\udffb\u200d\ud83e\uddb0: \uc0c1\ub300\uc640 \ub300\ud654\ub97c \ud558\uba74\uc11c \ub0b4\uac00 \ud558\uace0 \uc788\ub294 \uac83\uc774 \uacf5\uac10\uc778\uc9c0, \ub098\uc758 \uacbd\ud5d8\uc744 \ud6d1\uc5b4\ubcf4\ub294 \uac83\uc778\uc9c0 \uc0dd\uac01\ud574 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ub0b4\uac00 \uc9c1\uc5c5\uc774 \uc788\ub294 \uc0c1\ud0dc\uc5d0\uc11c \uce5c\uad6c\uc758 \ud574\uace0 \uc18c\uc2dd\uc744 \ub4e4\uc5c8\uc744 \ub54c\uc640, \uac19\uc774 \ud574\uace0 \ub2f9\ud588\uc744 \ub54c \ub0b4\uac00 \ud574\uc57c\ud558\ub294 \uacf5\uac10\uc740 \ub2e4\ub974\ub2e4. \uc804\uc790\ub294 \ub4e4\uc5b4\uc8fc\ub294 \uac83\uc774 \uacf5\uac10\uc774\uace0, \ud6c4\uc790\ub294 \uc5b5\uc6b8\ud568\uacfc \uace0\ubbfc\uc744 \ub098\ub204\ub294 \uac83\uc774 \uacf5\uac10\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4. \uacf5\uac10\ud558\uaca0\ub2e4\ub294 \uc774\uc720\ub85c \uc0c1\ub300\uc758 \uc774\uc57c\uae30\ub97c \ub0b4 \ucd08\uc810\uc73c\ub85c \ub3cc\ub9ac\uc9c0 \ub9d0\uc790.\\n\\n## \ud83d\udc69\ud83c\udffb\u200d\ud83c\udfeb 2. \uc120\uc0dd\ub2d8\uc774 \ub418\ub824\ub294 \uc695\uc2ec\uc744 \ubd80\ub9ac\uc9c0 \uc54a\ub294\ub2e4.\\n\\n\uc0ac\ub78c\ub4e4\uc774 \uae38\uac8c \uc124\uba85\ud558\ub824\ub294 \uc774\uc720\ub294 \uc0c1\ub300\ub97c \ud1b5\uc81c\ud558\uac70\ub098 \uc790\uc2e0\uc774 \uc778\uc815\ubc1b\uace0 \uc2f6\uae30 \ub54c\ubb38\uc774\ub2e4. \uc6b0\ub9ac\ub294 \ubb34\uc758\uc2dd\uc801\uc73c\ub85c \ud0c0\uc778\uc758 \uc138\uacc4\uad00\uc744 \ubbf8\uc131\uc219\ud558\uac8c \uc5ec\uae30\uace0, \ud3b8\uacac\uc744 \uac00\uc9c0\uace0 \uc0c1\ub300\uc758 \uc0dd\uac01\uc744 \uad50\uc815\ud558\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \ub300\ud654\uc758 \ubaa9\uc801\uc740 \uc0c1\ub300\ub97c \ubc14\uafb8\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub9c8\uc74c\uc744 \uc5ec\ub294 \uac83\uc774\ub2e4. \\"\ud639\uc2dc \uc0c1\ub300\uc758 \uc758\uacac\uc774 \uc62c\uc740\uac00?\\" \ud558\ub294 \uc5f4\ub9b0 \uc9c8\ubb38\uc744 \uac00\uc9c0\uace0 \uc811\uadfc\ud558\uba70, \ub098\uc758 \uacac\ud574\ub294 \uc7a0\uc2dc \ub0b4\ub824\ub193\uace0 \uc194\uc9c1\ud558\uace0 \uc815\uc911\ud558\uac8c \ub300\ud654\ub97c \ub098\ub204\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.\\n\\n\ub098\uc640 \ub2e4\ub978 \uc2e0\ub150\uc744 \uc9c0\ub2cc \ub204\uad70\uac00\uc640 \ub300\ud654\ub97c \ub098\ub20c \ub54c \ub2e4\uc74c \ub450 \uac00\uc9c0 \uc9c8\ubb38\uc744 \uae30\uc5b5\ud558\uc790.\\n- \\"\uc774 \ub300\ud654\ub85c \ubd80\ud130 \ubb34\uc5c7\uc744 \uc5bb\uc5b4\ub0b4\uae38 \ubc14\ub77c\ub294\uac00?\\"\\n- \\"\ub300\ud654\uac00 \ub05d\ub0a0 \ubb34\ub835 \uc5b4\ub5a4 \uae30\ubd84\uc744 \ub290\ub07c\uae30 \ubc14\ub77c\ub294\uac00?\\"\\n\ub300\ud654\ub97c \ud1b5\ud574 \uc0c1\ub300\uac00 \uc5bb\uac8c\ub420 \ud61c\ud0dd\uc744 \uacb0\uc815\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ub0b4 \uc2a4\uc2a4\ub85c\uac00 \uc5bb\uac8c\ub420 \ud61c\ud0dd\uc744 \uacb0\uc815\ud560 \uc218 \uc788\ub2e4.\\n\\n\ud83d\udc69\ud83c\udffb\u200d\ud83e\uddb0: \uc5b4\ub5a4 \uce5c\uad6c\uc5d0\uac8c\ub294 \uc870\uc5b8\uc744 \uad6c\ud558\uace0 \ub610 \ub2e4\ub978 \uc5b4\ub5a4 \uce5c\uad6c\uc5d0\uac8c\ub294 \ud56d\uc0c1 \uc870\uc5b8\uc744 \ud55c\ub2e4\uba74 \ubb34\uc758\uc2dd\uc801\uc73c\ub85c \ub0b4\uac00 \'\uc800 \uce5c\uad6c\ubcf4\ub2e4 \ub098\uc544\' \ub77c\ub294 \uc0dd\uac01\uc744 \uac00\uc9c0\uace0 \uc788\ub294\uac8c \uc544\ub2d0\uae4c?\\n\\n## \ud83d\ude4b\ud83c\udffb 3. \uc9c8\ubb38\uc744 \ud1b5\ud574 \uad00\uc2ec\uacfc \uc0ac\ub791\uc744 \ud45c\ud604\ud55c\ub2e4.\\n\\n\uac1c\ubc29\ud615 \uc9c8\ubb38\ub4e4\uc740 \uc0c1\ub300\uc5d0\uac8c \uadf8 \uc790\uc2e0\ub9cc\uc758 \uc5b8\uc5b4\ub85c \ubb34\uc2a8 \uc77c\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0 \ubb18\uc0ac\ud560 \uc218 \uc788\ub3c4\ub85d \uacf5\uac04\uc744 \ub9c8\ub828\ud574\uc900\ub2e4. \ud3d0\uc1c4\ud615 \uc9c8\ubb38\uc740 \uad6c\uccb4\uc801\uc774\uace0, \uac04\ub2f9\uba85\ub8cc\ud558\uba70, \ube60\ub978 \ub2f5\ubcc0\uc744 \uc774\ub04c\uc5b4 \ub0b8\ub2e4. \ud3d0\uc1c4\ud615 \uc9c8\ubb38\uc740 \uc9c8\ubb38\uc790\uac00 \ub300\ud654\uc5d0 \ub300\ud55c \ud1b5\uc81c\uad8c\uc744 \uacc4\uc18d\ud574\uc11c \ubcf4\uc720\ud55c\ub2e4\ub294 \uce21\uba74\uc774 \uc788\ub2e4. \uc9c8\ubb38\uc5d0\ub294 \ub300\ud654\ub97c \uc774\ub04c\uc5b4\uac00\ub294 \uc2e4\ub85c \uac15\ub825\ud55c \ud798\uc774 \ub2f4\uaca8 \uc788\ub2e4. \ud558\uc9c0\ub9cc, \uc798\ubabb\ub41c \uc9c8\ubb38\uc73c\ub85c \uc0c1\ub300\uc640\uc758 \uad00\uacc4\ub97c \ub9dd\uce60\uc218\ub3c4 \uc788\ub2e4. \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \uac83\uc5d0\ub3c4 \uae30\uc220\uc774 \ud544\uc694\ud558\ub2e4. \uc9c8\ubb38\uc758 \uc9c8\uc744 \ud5a5\uc0c1\uc2dc\ud0a4\ub824\uba74 \uc9c8\ubb38\uc744 \ub9ce\uc774 \ub358\uc838 \ubd10\uc57c \ud55c\ub2e4. **\uc9c8\ubb38\uc740 \uc0c1\ub300\uc5d0 \ub300\ud55c \ud638\uae30\uc2ec\uc758 \ud45c\ucd9c\uc774\uace0, \ub0b4\uac00 \uc0c1\ub300\ub97c \uc0ac\ub791\ud558\uace0 \uc788\ub2e4\ub294 \uac00\uc7a5 \ud070 \uc99d\uac70\uc774\ub2e4.**\\n\\n\ud83d\udc69\ud83c\udffb\u200d\ud83e\uddb0: \uc88b\uc740 \uc9c8\ubb38 \uba87\uac1c \ub9cc\uc73c\ub85c\ub3c4 \uadf8 \ub300\ud654\uac00 \uc720\uc775\ud588\ub2e4\ub77c\ub294 \ub290\ub08c\uc774 \ub4e4\uae30\ub3c4 \ud55c\ub2e4. \ubc18\uba74, \uc9c8\ubb38\uc73c\ub85c \ubc29\uc5b4\uc801\uc778 \uac10\uc815\uc744 \ubd88\ub7ec\uc77c\uc73c\ud0a4\uae30\ub3c4 \ud55c\ub2e4. \uc774 \ub458\uc758 \ucc28\uc774\ub294 \ubb58\uae4c? \uc9c8\ubb38\uc740 \ub2e8\uc21c\ud55c \ub300\ud654 \uc218\ub2e8\uc774 \uc544\ub2c8\ub77c \uc0c1\ub300\uc5d0 \ub300\ud55c \ub9c8\uc74c\uac00\uc9d0\uc744 \ub4dc\ub7ec\ub0b4\uba70, \uc9c8\ubb38\uc758 \ub2f4\uae34 \ud0dc\ub3c4\uc640 \ud488\uaca9\uc744 \ud1b5\ud574 \uc0c1\ub300\ub97c \uc874\uc911\ud558\ub294 \ub9c8\uc74c\uc774 \uc804\ud574\uc9c0\uae30\ub3c4 \ud55c\ub2e4.\\n\\n## \ud83e\udd25 4. \ub300\ucda9 \uc544\ub294 \uac83\uc744 \uc798 \uc544\ub294 \ucc99\ud558\uc9c0 \uc54a\ub294\ub2e4.\\n\\n\uc9c4\uc2e4\uc744 \ub9d0\ud558\ub294 \uac83\uc740 \uc2e0\ub8b0\ub97c \uc313\uace0 \uc815\uc9c1\ud55c \uc778\uc0c1\uc744 \uc900\ub2e4. \ub610\ud55c, \uc790\uc2e0\uc758 \uc624\ub958 \uac00\ub2a5\uc131\uc744 \uc778\uc815\ud568\uc73c\ub85c\uc368 \uacb8\uc190\ud574 \uc9c8 \uc218 \uc788\ub2e4. \uc798 \ubaa8\ub974\ub294 \uc8fc\uc81c\uc5d0 \ub300\ud574 \uc544\ub294 \ucc99\ud558\uc9c0 \ub9c8\ub77c. \uc9c8\ubb38\uc5d0 \ub300\ub2f5\ud558\uc9c0 \ubabb\ud558\uba74 \uc0c1\ub300\ub294 \uac70\uc9d3\ub9d0\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \uc6b0\ub9ac\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub611\ub611\ud558\ub2e4\uace0 \uc0dd\uac01\ud574\uc8fc\uae38 \ubc14\ub77c\uac70\ub098, \uc57d\uc810\uc744 \ub4dc\ub7ec\ub0b4\uae30 \uaebc\ub824\uc11c \uc544\ub294 \ucc99\uc744 \ud558\uc9c0\ub9cc, \uc624\ud788\ub824 \uc2e0\ub8b0\ub97c \uc783\uac8c \ub9cc\ub4e0\ub2e4. \\"\uc798 \ubaa8\ub985\ub2c8\ub2e4\\" \ub77c\ub294 \ub9d0\uc744 \ud1b5\ud574 \uc790\uc2e0\uc758 \ud55c\uacc4\ub97c \uc778\uc815\ud558\ub294 \uac83\uc774 \uc720\ub300\uac10\uc744 \uac15\ud654\uc2dc\ucf1c \uc904 \uac83\uc774\uace0, \uc131\uc7a5\uacfc \ubc30\uc6c0\uc758 \uae30\ud68c\ub97c \uc5f4\uc5b4\uc900\ub2e4. \ub300\ud654\ub294 \uad00\uacc4\uc758 \uae30\ubc18\uc774\uba70, \uad00\uacc4\ub294 \uc2e0\ub8b0\ub97c \ud1a0\ub300\ub85c \ud55c\ub2e4. \ub2f9\uc2e0\uc740 \'\uc790\uae30 \uc9c0\uc2dd\uc758 \ud55c\uacc4\uc5d0 \ub300\ud574 \ub354 \uc194\uc9c1\ud574\uc9c0\uba74 \uc9c8\uc218\ub85d, \uc0ac\ub78c\ub4e4\uc774 \ub2f9\uc2e0\uc758 \uc758\uacac\uc5d0 \uadf8\ub9cc\ud07c \ub354 \ubb34\uac8c\ub97c \ub454\ub2e4\'\ub294 \uc0ac\uc2e4\uc744 \ubc1c\uacac\ud558\uac8c \ub420 \uac83\uc774\ub2e4. \\n\\n## \ud83e\udec0 5. \uadc0\uac00 \uc544\ub2cc \ub9c8\uc74c\uc73c\ub85c \ub4e3\ub294\ub2e4.\\n\\n\ud63c\uc7a3\ub9d0\uc744 \ud574\ub3c4 \ub450\ub1cc\uc758 \ucf8c\ub77d \uc911\ucd94\uac00 \ud65c\uc131\ud654 \ub41c\ub2e4. \uc989, \uc6b0\ub9ac\ub294 \uc790\uc2e0\uc5d0 \ub300\ud574 \uc774\uc57c\uae30 \ud558\ub294 \uac83\uc744 \uc120\ud638\ud55c\ub2e4. \ub4e3\ub294 \uac83(hearing)\uacfc \uae30 \uae30\uc6b8\uc5ec \ub4e3\ub294\uac83(listening)\uc740 \ub2e4\ub974\ub2e4. \ub4e3\uae30\uc758 \uc131\uacf5\uc740 \uae30\uc5b5\uc5d0 \ub0a8\ub294 \ub0b4\uc6a9\uc73c\ub85c \ud3c9\uac00\ud560 \uc218 \uc788\ub294\ub370, \ub0b4\uc6a9\uc758 \uc808\ubc18 \uc774\uc0c1\uc744 \uc78a\uc5c8\ub2e4\uba74 \uc81c\ub300\ub85c \ub4e3\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \ud604\ub300\uc758 \uc628\ub77c\uc778 \ub9e4\uccb4\ub294 \uc6b0\ub9ac\ub97c \uc694\uc810\ub9cc \ud6d1\uc5b4\ubcf4\uac8c \ub9cc\ub4e4\uc5b4, \'\ud2b8\uc704\ud130 \ub450\ub1cc(twitter brain)\'\uc744 \ud615\uc131\ud558\uace0 \uc788\ub2e4. \uc9c4\uc815\ud55c \uccad\ucde8\ub294 \ube44\uc5b8\uc5b4\uc801 \ud45c\ud604\uae4c\uc9c0 \uc774\ud574\ud558\uace0, \ub0b4\uc6a9\uc5d0 \ubc18\uc751\ud558\uba70 \uc694\uc57d\ud558\ub294 \ub2a5\ub3d9\uc801\uc778 \uacfc\uc815\uc774\ub2e4.\\n\\n\ud83d\udc69\ud83c\udffb\u200d\ud83e\uddb0: \ub300\ud654 \ud560 \ub54c \ub098\ub294 \ub4e3\uace0 \uc788\ub294\uac00? \uc0c1\ub300\uc758 \uc774\uc57c\uae30\ub97c \ub4e4\uc744 \ub54c 80%\ub294 \uadf8\ub0e5 \ud758\ub824 \ub4e3\ub294 \uac83 \uac19\ub2e4. \ubb3c\ub860 \uc77c\ubd80\ub85c \ub4e3\uc9c0 \uc54a\ub294\uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\uc7a5\uc774 \uae38\uc5b4\uc9c0\uace0, \ub300\ud654\uac00 \uae38\uc5b4\uc9c0\uba74 \uc55e\uc5d0 \ub0b4\uc6a9\uc744 \uc78a\uc5b4\ubc84\ub9b0\ub2e4. \uadc0 \uae30\uc6b8\uc5ec \ub4e3\ub294 \ud589\uc704\uac00 \uc0c1\ub300\ub97c \uae4a\uc774 \uc874\uc911\ud558\ub294 \ud589\uc704\uc774\ub2e4. \ud2b8\uc704\ud130 \ub450\ub1cc\uc5d0\uc11c \ubc97\uc5b4\ub098 \uc804\uccb4\ub97c \uc77d\uace0 \uc694\uc57d\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc5ec\ubcf4\uc790. \\n\\n## \ud83d\udce1 6. \uc0c1\ub300\uac00 \ubcf4\ub0b4\ub294 \uc2e0\ud638\uc5d0 \uc548\ud14c\ub098\ub97c \uc138\uc6b4\ub2e4.\\n\\n\ub9d0\ud558\ub294 \uc911\uac04 \uc911\uac04\uc5d0 \uc0c1\ub300\uc758 \ubc18\uc751\uc744 \ud30c\uc545\ud574 \uac00\uba70 \ub9d0\ud574\uc57c \ud55c\ub2e4. \ub300\ud654\ub97c \uc2dc\uc791\ud558\uae30 \uc804, \ub300\ud654\ub97c \ud1b5\ud574 \uc5bb\uace0\uc790 \ud558\ub294 \uac83\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc7a0\uc2dc \uc0dd\uac01\ud558\ub294 \uc2dc\uac04\uc744 \uac00\uc9c8 \ud544\uc694\uac00 \uc788\ub2e4. \ub300\ud654\uc758 \ub0b4\uc6a9\uc740 \uc0c1\ud638\uac04\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \uacb0\uc815\ub418\uc5b4\uc57c \ud55c\ub2e4.\\n\\n## \ud83c\udf3f 7. \uc7a1\ucd08 \ubc2d\uc5d0 \ub4e4\uc5b4\uac00 \ubc30\ud68c\ud558\uc9c0 \uc54a\ub294\ub2e4.\\n\\n\ubd88\ud544\uc694\ud55c \uc138\ubd80 \ubb18\uc0ac\ub294 \uc774\uc57c\uae30\uc758 \ud750\ub984\uc744 \ubc29\ud574\ud558\uace0 \ud765\ubbf8\ub97c \ub5a8\uc5b4\ub728\ub9ac\uba70, \uc774\ub97c \'\uc7a1\ucd08\ubc2d\uc73c\ub85c \ub4e4\uc5b4\uac00\uae30\'\ub77c\uace0 \ud45c\ud604\ud55c\ub2e4. \uc9c0\ub098\uce5c \uc138\ubd80 \ubb18\uc0ac \ubfd0\ub9cc\uc544\ub2c8\ub77c, \uc0c1\ub300\ubc29\uc774 \ud55c \uc598\uae30 \uac00\uc6b4\ub370 \uc798\ubabb\ub41c \ub0b4\uc6a9\uc744 \uad50\uc815\ud558\uace0\uc790 \ud558\ub294 \ucda9\ub3d9\ub3c4 \ub9c8\ucc2c\uac00\uc9c0 \uc774\ub2e4. \uc0ac\uc18c\ud55c \uac83\uc774\ub77c\uba74 \uad73\uc774 \uad50\uc815\ud558\uc9c0\ub294 \ub9d0\uc790. \\n\\n\ubb3c\ub860 \uc608\uc678 \uc0c1\ud669\uc740 \uc788\ub2e4. \uc554 \ud22c\ubcd1\uc744 \ud558\ub294 \uce5c\uad6c\uc758 \uc774\uc57c\uae30\ub97c \ub4e4\uc5b4\uc8fc\ub294 \uac83\uc740 \uc0ac\ub791\uc744 \ud45c\ud604\ud558\ub294 \ud558\ub098\uc758 \ubc29\uc2dd\uc774\ub2e4. **\ub300\ud654\uac00 \ud56d\uc0c1 \ubaa9\uc801 \uc9c0\ud5a5\uc801\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4.** \uc608\uc678 \uc0c1\ud669\uc744 \uc81c\uc678\ud558\uace0\ub294 \uc720\uc775\ud55c \ub300\ud654\ub97c \uc704\ud574 \uc138\ubb34 \ubb18\uc0ac\uc640 \uad50\uc815\uc740 \ud53c\ud574\uc57c \ud55c\ub2e4.\\n\\n\ud83d\udc69\ud83c\udffb\u200d\ud83e\uddb0: \ub4e3\uae30 \uc88b\uc740 \uc774\uc57c\uae30\uc5d0 \ub300\ud574 \ubc18\uc751\ud558\ub294 \uac83\uc740 \uc27d\uc9c0\ub9cc, \ub4e3\uace0 \uc2f6\uc9c0 \uc54a\uc740 \uc774\uc57c\uae30\uc5d0 \ubc18\uc751\ud558\ub294 \uac83\uc740 \uc5b4\ub835\ub2e4. \ub0b4\uac00 \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c\uc774\ub77c\uba74 \uc870\uae08 \uae30\ub2e4\ub824\uc8fc\uace0 \uadc0 \uae30\uc6b8\uc5ec \uc904 \ud544\uc694\uac00 \uc788\ub2e4. \ubc18\ub300\uc758 \uc0c1\ud669\ub3c4 \ub9c8\ucc2c\uac00\uc9c0 \uc774\ub2e4. \ubaa9\uc801\uc758\uc2dd\uc5d0 \ubd80\ud569\ud55c \uc774\uc57c\uae30\ub9cc \ud558\ub824\uace0 \ub108\ubb34 \uc2a4\uc2a4\ub85c\ub97c \uc5b5\uc555\ud558\uc9c0 \ub9d0\uc790. \\n\\n> p.105 \ubb3c\ub860 \ub450\uc11c\uc5c6\uace0 \ubc29\ud5a5\uc774 \uc5c6\ub294 \ub300\ud654\uac00 \ud544\uc694\ud560 \ub54c\ub3c4 \uc788\ub2e4. \ubaa8\ub4e0 \ub300\ud654\uac00 \ubaa9\ud45c\ub97c \ud5a5\ud574 \ubaa9\uc801\uc758\uc2dd\uc801\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c8 \ud544\uc694\ub294 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \\"\uc544\ub4e4\uc774 \uc544\ubb34\ub9ac \ub9ce\uc740 \ub9d0\uc744 \ub298\uc5b4\ub193\uc744 \uc9c0\ub77c\ub3c4 \uc55e\uc73c\ub85c\ub3c4 \uacc4\uc18d\ud574\uc11c \uc544\ub4e4\uc758 \ub9d0\uc744 \ub4e4\uc5b4\uc904 \uc0dd\uac01\uc774\ub2e4. \ub0b4\uac00 \uadf8\ub807\uac8c \ud558\ub294 \uc774\uc720\ub294 \ub0b4\uac00 \uadf8\uc758 \uc5c4\ub9c8\uc774\uace0, \uadf8\ub97c \uc9c0\uad6c\uc0c1\uc758 \uadf8 \ub204\uad6c\ubcf4\ub2e4\ub3c4 \uc0ac\ub791\ud558\uae30 \ub584\ubb38\uc774\ub2e4.\\" \uc138\ubd80 \ub0b4\uc6a9\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc774\ub294 \uac83\uc740 \uc5b4\ub824\uc6c0\uc5d0 \ucc98\ud55c \uce5c\uad6c\uc5d0\uac8c \ud574\uc904 \uc218 \uc788\ub294 \ud558\ub098\uc758 \ubd09\uc0ac \uc218\ub2e8\uc774\uae30\ub3c4 \ud558\ub2e4. \uc554\uc744 \uc9c4\ub2e8 \ubc1b\uc740 \uce5c\uad6c\ub294 \ucd5c\ub300\ud55c \uc138\uc138\ud558\uac8c \uadf8\uac00 \uacaa\uc740 \uc77c\ub4e4\uc744 \ud138\uc5b4 \ub193\uace0 \uc2f6\uc5b4 \ud560 \uac83\uc774\ub2e4. \uc774\ub7f0 \uacbd\uc6b0\uc5d0 \uadf8 \uc598\uae30\ub97c \ub4e4\uc5b4\uc8fc\ub294 \uac83\uc740 \uc0ac\ub791\uc744 \ud45c\ud604\ud558\ub294 \ud558\ub098\uc758 \ubc29\uc2dd\uc774 \ub420 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774\uac83\uc740 \uc608\uc678 \uc0c1\ud669\uc774\ub2e4. \uc11c\ub85c \uacf5\uac10\ud560 \uc218 \uc788\uace0 \uc720\uc775\ud55c \uc758\uacac\uc744 \uad50\ud658\ud558\ub824\uba74 \uc0ac\uc18c\ud55c \ub0b4\uc6a9\uc744 \uc5b8\uae09\ud558\ub294 \uc77c\uc740 \ub418\ub3c4\ub85d \ud53c\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4.\\n\\n> p.108 \uc0c1\ub300\uc758 \ub9d0\uc774\ub098 \uc778\uc2dd\uc744 \uad50\uc815\ud574\uc8fc\ub294 \uac83\uc774 \uc815\ub9d0\ub85c \ud544\uc694\ud558\uace0 \uc808\uc2e4\ud55c \uc0c1\ud669\uc774\ub77c\uba74, \ub2e4\ub978 \ubc29\ubc95\uc744 \ucc3e\uc544\ubcf4\uac70\ub098 \uc0c1\ub300\uac00 \ub9d0\uc744 \ub2e4 \ub9c8\uce60 \ub54c \uae4c\uc9c0 \uae30\ub2e4\ub824 \uc8fc\uc790. \uadf8\ub9ac\uace0 \ub9cc\uc77c \uadf8 \uad50\uc815\ud574\uc57c\ud560 \uc0ac\ud56d\uc774 \uc0ac\uc18c\ud55c \uac83\uc774\ub77c\uba74 \uad73\uc774 \uad50\uc815\ud558\ub294 \uc77c\uc740 \ud558\uc9c0 \ub9d0\uc790. \uadf8\ub7f0 \ub9d0\uc744 \ud558\ub294 \uac83\uc774 \uc815\ub9d0\ub85c \ud544\uc694\ud55c\uc9c0 \uc758\uc2dd\uc801\uc73c\ub85c \uace0\ub824\ud558\uc9c0\ub3c4 \uc54a\uc740 \ucc44, \uc0c1\ub300\ubc29\uc758 \uc2e4\uc218\ub97c \uc9c0\uc801\ud558\uac70\ub098, \ubc14\ub85c\uc7a1\uc744 \ud544\uc694\uac00 \uc5c6\ub294 \uc0ac\uc2e4\uc744 \ubc14\ub85c\uc7a1\ub294 \uacbd\uc6b0\uac00 \ub108\ubb34\ub098\ub3c4 \ub9ce\uae30 \ub54c\ubb38\uc774\ub2e4."}]}}')}}]);